// =========================================
// SALES-1G-B — COMPACT SALE DATA
// =========================================

function prepareNexodraSaleForOfflineCache(sale) {

    if (!sale || !sale.id) {
        return null;
    }

    const compactItems = (
        Array.isArray(sale.items) ? sale.items : []
        ).map(item => ({
        productId: item.productId || item.product_id || null,

        title: item.title || item.name || 'Unnamed product',

        quantity: Number(item.quantity) || 0,

        price: Number(item.price) || 0,

        // Preserve the cost snapshot for accurate future COGS.
        costPrice:
            item.costPrice ??
            item.cost_price ??
            item.unitCost ??
            item.unit_cost ??
            item.purchasePrice ??
            item.purchase_price ??
            null
    }));

    return {
        id: sale.id,
        owner_id: sale.owner_id || null,
        items: compactItems,
        items_count: Number(sale.items_count) || 0,
        subtotal: Number(sale.subtotal) || 0,
        discount: Number(sale.discount) || 0,
        tax: Number(sale.tax) || 0,
        total: Number(sale.total) || 0,
        customer_name: sale.customer_name || 'Walk-in Customer',
        note: sale.note || '',
        payment_method: sale.payment_method || 'cash',
        created_at: sale.created_at || null,
        updated_at: sale.updated_at || null
    };
}

// =========================================
// SALES-1G-C — SAVE SALE TO INDEXEDDB
// =========================================

async function saveNexodraSaleToIndexedDB(userId, sale) {

    try {

        if (!userId || !sale) {
            return false;
        }

        const compactSale =
            prepareNexodraSaleForOfflineCache(sale);

        if (!compactSale) {
            return false;
        }

        compactSale.cacheKey =
            `${userId}:${compactSale.id}`;

        const db = await openNexodraSalesDB();

        return await new Promise((resolve, reject) => {

            const transaction =
                db.transaction(
                    'completedSales',
                    'readwrite'
                );

            const store =
                transaction.objectStore('completedSales');

            store.put(compactSale);

            transaction.oncomplete = () => {
                console.log(
                    'SALES-1G-C — Compact sale saved:',
                    compactSale.id
                );
                resolve(true);
            };

            transaction.onerror = () => {
                reject(transaction.error);
            };

            transaction.onabort = () => {
                reject(transaction.error);
            };

        });

    } catch (error) {

        console.error(
            'SALES-1G-C — IndexedDB save failed:',
            error
        );

        return false;
    }
}

// =========================================
// SALES-1G-D — LOAD SALE FROM INDEXEDDB
// =========================================

async function getNexodraSaleFromIndexedDB(userId, saleId) {

    try {

        if (!userId || !saleId) {
            return null;
        }

        const cacheKey = `${userId}:${saleId}`;

        const db = await openNexodraSalesDB();

        return await new Promise((resolve, reject) => {

            const transaction =
                db.transaction(
                    'completedSales',
                    'readonly'
                );

            const store =
                transaction.objectStore('completedSales');

            const request = store.get(cacheKey);

            request.onsuccess = () => {

                const sale = request.result || null;

                console.log(
                    'SALES-1G-D — IndexedDB lookup:',
                    {
                        saleId: saleId,
                        found: !!sale
                    }
                );

                resolve(sale);

            };

            request.onerror = () => {
                reject(request.error);
            };

        });

    } catch (error) {

        console.error(
            'SALES-1G-D — IndexedDB lookup failed:',
            error
        );

        return null;
    }
}

// =========================================
// SALES-1G-F-A — BATCH SAVE TO INDEXEDDB
// =========================================

async function saveNexodraSalesBatchToIndexedDB(userId, sales) {

    try {

        if (!userId || !Array.isArray(sales)) {
            return false;
        }

        const compactSales = sales
            .map(sale =>
                prepareNexodraSaleForOfflineCache(sale)
            )
            .filter(Boolean)
            .map(sale => ({
                ...sale,
                cacheKey: `${userId}:${sale.id}`
            }));

        const db = await openNexodraSalesDB();

        return await new Promise((resolve, reject) => {

            const transaction = db.transaction(
                'completedSales',
                'readwrite'
            );

            const store = transaction.objectStore(
                'completedSales'
            );

            compactSales.forEach(sale => {
                store.put(sale);
            });

            transaction.oncomplete = () => {

                console.log(
                    'SALES-1G-F-A — Batch saved to IndexedDB:',
                    compactSales.length
                );

                resolve(true);
            };

            transaction.onerror = () => {
                reject(transaction.error);
            };

            transaction.onabort = () => {
                reject(transaction.error);
            };

        });

    } catch (error) {

        console.error(
            'SALES-1G-F-A — Batch save failed:',
            error
        );

        return false;
    }
}

// =========================================
// SALES-1G-F-B — LOAD USER SALES FROM INDEXEDDB
// =========================================

async function loadNexodraSalesBatchFromIndexedDB(userId) {

    try {

        if (!userId) {
            return [];
        }

        const db = await openNexodraSalesDB();

        return await new Promise((resolve, reject) => {

            const transaction = db.transaction(
                'completedSales',
                'readonly'
            );

            const store = transaction.objectStore(
                'completedSales'
            );

            const request = store.getAll();

            request.onsuccess = () => {

                const userPrefix = `${userId}:`;

                const userSales = (request.result || [])
                    .filter(sale =>
                        typeof sale.cacheKey === 'string' &&
                        sale.cacheKey.startsWith(userPrefix)
                    )
                    .map(sale => {
                        const { cacheKey, ...saleData } = sale;
                        return saleData;
                    });

                console.log(
                    'SALES-1G-F-B — User sales loaded from IndexedDB:',
                    userSales.length
                );

                resolve(userSales);
            };

            request.onerror = () => {
                reject(request.error);
            };

        });

    } catch (error) {

        console.error(
            'SALES-1G-F-B — IndexedDB load failed:',
            error
        );

        return [];
    }
}

// =========================================
// SALES-1G-F-C — BATCH SAVE/LOAD TEST
// =========================================

async function testNexodraSalesBatchIndexedDB() {

    try {

        const {
            data: { session },
            error
        } = await supabaseClient.auth.getSession();

        const user = session?.user || null;

        if (error || !user) {
            console.warn(
                'SALES-1G-F-C — No authenticated user.'
            );
            return false;
        }

        // Read existing localStorage cache
        const oldCachedSales =
            loadNexodraSalesCache(user.id);

        console.log(
            'SALES-1G-F-C — Existing local sales:',
            oldCachedSales.length
        );

        if (!oldCachedSales.length) {
            console.warn(
                'SALES-1G-F-C — No old cached sales to test.'
            );
            return false;
        }

        // Save all existing records as a batch
        const saved =
            await saveNexodraSalesBatchToIndexedDB(
                user.id,
                oldCachedSales
            );

        // Read them back from IndexedDB
        const loaded =
            await loadNexodraSalesBatchFromIndexedDB(
                user.id
            );

        console.log(
            'SALES-1G-F-C — Batch test result:',
            {
                sourceCount: oldCachedSales.length,
                saved: saved,
                loadedCount: loaded.length,
                passed: saved && loaded.length >= oldCachedSales.length
            }
        );

        return saved && loaded.length >= oldCachedSales.length;

    } catch (error) {

        console.error(
            'SALES-1G-F-C — Test failed:',
            error
        );

        return false;
    }
}

// =========================================
// SALES-1G-E — TEST INDEXEDDB SAVE + LOAD
// =========================================

async function testNexodraSalesIndexedDB() {

    try {

        const {
            data: { session },
            error
        } = await supabaseClient.auth.getSession();

        if (error || !session?.user) {
            console.warn(
                'SALES-1G-E — No authenticated user.'
            );
            return;
        }

        const userId = session.user.id;

        const cachedSales =
            loadNexodraSalesCache(userId);

        if (!cachedSales.length) {
            console.warn(
                'SALES-1G-E — No existing sale available for test.'
            );
            return;
        }

        const testSale = cachedSales[0];

        const saved = await saveNexodraSaleToIndexedDB(
            userId,
            testSale
        );

        const loaded = await getNexodraSaleFromIndexedDB(
            userId,
            testSale.id
        );

        console.log(
            'SALES-1G-E — IndexedDB test result:',
            {
                saleId: testSale.id,
                saved: saved,
                loaded: !!loaded,
                productCount: loaded?.items?.length || 0,
                firstProduct: loaded?.items?.[0]?.title || null,
                firstProductHasImage:
                    loaded?.items?.[0]
                        ? Object.prototype.hasOwnProperty.call(
                            loaded.items[0],
                            'image'
                        )
                        : false
            }
        );

    } catch (error) {

        console.error(
            'SALES-1G-E — Test failed:',
            error
        );

    }
}

testNexodraSalesIndexedDB();

// Get a separate cache key for each account.
function getNexodraSalesCacheKey(userId) {

    if (!userId) {
        return null;
    }

    return (
        NEXODRA_SALES_CACHE_PREFIX +
        String(userId)
    );
}


// Save completed sales locally.
function saveNexodraSalesCache(userId, sales) {

    const cacheKey =
        getNexodraSalesCacheKey(userId);

    if (!cacheKey || !Array.isArray(sales)) {
        return false;
    }

    try {

        localStorage.setItem(
            cacheKey,
            JSON.stringify(sales)
        );

        console.log(
            'SALES-1B — Local sales cache saved:',
            sales.length
        );

        return true;

    } catch (error) {

        console.error(
            'SALES-1B — Could not save local sales cache:',
            error
        );

        return false;
    }
}




// =========================================
// SALES-1F-A — CACHE ALL SELLER SALES
// =========================================

async function cacheAllSellerSales() {

    try {

        // Read the locally saved authenticated session.
        const {
            data: { session },
            error: sessionError
        } = await supabaseClient.auth.getSession();

        const user = session?.user || null;

        if (sessionError || !user) {
            console.warn(
                'SALES-1F-A — No authenticated session.'
            );
            return false;
        }

        const pageSize = 500;
        let start = 0;
        let allFetchedSales = [];

        // Fetch the seller's sales in manageable pages.
        while (true) {

            const {
                data: salesPage,
                error: salesError
            } = await supabaseClient
                .from('sales')
                .select(`
                    id,
                    owner_id,
                    items,
                    items_count,
                    subtotal,
                    discount,
                    tax,
                    total,
                    customer_name,
                    note,
                    payment_method,
                    created_at,
                    updated_at
                `)
                .eq('owner_id', user.id)
                .order('created_at', {
                    ascending: false
                })
                .range(start, start + pageSize - 1);

            if (salesError) {
                console.error(
                    'SALES-1F-A — Sales fetch failed:',
                    salesError
                );
                return false;
            }

            const page = salesPage || [];

            allFetchedSales.push(...page);

            if (page.length < pageSize) {
                break;
            }

            start += pageSize;
        }

        // SALES-1G-G-A — SAVE ALL HISTORY TO INDEXEDDB

const existingSales =
    await loadNexodraSalesBatchFromIndexedDB(user.id);

const fetchedIds = new Set(
    allFetchedSales.map(sale =>
        String(sale.id)
    )
);

const mergedSales = [
    ...allFetchedSales,
    ...existingSales.filter(sale =>
        !fetchedIds.has(String(sale.id))
    )
];

const saved =
    await saveNexodraSalesBatchToIndexedDB(
        user.id,
        mergedSales
    );
      
        console.log(
            'SALES-1F-A — All-history cache result:',
            {
                fetched: allFetchedSales.length,
                previouslyCached: existingSales.length,
                totalCached: mergedSales.length,
                saved: saved
            }
        );

        return saved;

    } catch (error) {

        console.error(
            'SALES-1F-A — Unexpected error:',
            error
        );

        return false;
    }
}

// Read completed sales from local storage.
function loadNexodraSalesCache(userId) {

    const cacheKey =
        getNexodraSalesCacheKey(userId);

    if (!cacheKey) {
        return [];
    }

    try {

        const savedSales =
            localStorage.getItem(cacheKey);

        if (!savedSales) {
            return [];
        }

        const parsedSales =
            JSON.parse(savedSales);

        if (!Array.isArray(parsedSales)) {
            return [];
        }

        console.log(
            'SALES-1B — Local sales cache loaded:',
            parsedSales.length
        );

        return parsedSales;

    } catch (error) {

        console.error(
            'SALES-1B — Could not load local sales cache:',
            error
        );

        return [];
    }
}

// =========================================
// BRICK 1G — AUTOMATIC OFFLINE SALES SYNC
// =========================================

let odropOfflineSaleSyncRunning = false;


async function syncOdropOfflineSales() {

    // Already syncing
    if (odropOfflineSaleSyncRunning) {
        console.log(
            'BRICK 1G — Sync already running.'
        );

        return;
    }


    // No internet
    if (!navigator.onLine) {
        console.log(
            'BRICK 1G — Device is offline. Sync skipped.'
        );

        return;
    }


    // No queued sales
    if (
        !odropOfflineSalesQueue ||
        odropOfflineSalesQueue.length === 0
    ) {
        console.log(
            'BRICK 1G — No offline sales waiting.'
        );

        return;
    }


    odropOfflineSaleSyncRunning = true;


    console.log(
        'BRICK 1G — Starting offline sales sync:',
        odropOfflineSalesQueue.length
    );


    try {

        // Get the current authenticated user.
        const {
            data: {
                user
            },
            error: userError
        } =
            await supabaseClient.auth.getUser();


        if (userError || !user) {

            console.error(
                'BRICK 1G — Could not get authenticated user:',
                userError
            );

            return;
        }


        // Only sync sales belonging to this user.
        const pendingSales =
            odropOfflineSalesQueue.filter(
                sale =>
                    sale &&
                    sale.syncStatus === 'pending' &&
                    String(sale.userId || '') ===
                    String(user.id)
            );


        if (pendingSales.length === 0) {

            console.log(
                'BRICK 1G — No pending sales for current user.'
            );

            return;
        }


        console.log(
            'BRICK 1G — Pending sales found:',
            pendingSales.length
        );


        // Process sales one at a time.
        for (
            const offlineSale
            of pendingSales
        ) {

            // Internet may disappear during sync.
            if (!navigator.onLine) {

                console.log(
                    'BRICK 1G — Internet lost during sync.'
                );

                break;
            }


            console.log(
                'BRICK 1G — Syncing sale:',
                offlineSale.localSaleId
            );


            const {
                data: saleId,
                error: saleError
            } =
                await supabaseClient.rpc(
                    'complete_sale',
                    {

                        p_items:
                            offlineSale.items,

                        p_items_count:
                            offlineSale.itemsCount,

                        p_subtotal:
                            offlineSale.subtotal,

                        p_discount:
                            offlineSale.discount,

                        p_tax:
                            offlineSale.tax,

                        p_total:
                            offlineSale.total,

                        p_customer_name:
                            offlineSale.customerName,

                        p_note:
                            offlineSale.note || '',

                        p_payment_method:
                            offlineSale.paymentMethod ||
                            'cash'

                    }
                );


            if (saleError) {

                console.error(
                    'BRICK 1G — Sale sync failed:',
                    offlineSale.localSaleId,
                    saleError
                );

                // Leave this sale in the queue.
                // It will be retried later.
                continue;
            }


            console.log(
                'BRICK 1G — Sale synchronized successfully:',
                {
                    localSaleId:
                        offlineSale.localSaleId,

                    supabaseSaleId:
                        saleId
                }
            );

          // P2-06D — Record movement after server confirms offline sale.
window.ODROP_INVENTORY_LOCAL.recordSaleMovements(
    saleId,
    offlineSale.items,
    'offline-pos-sync'
);

            // Remove ONLY the successfully
            // synchronized sale from the queue.
            odropOfflineSalesQueue =
                odropOfflineSalesQueue.filter(
                    sale =>
                        sale.localSaleId !==
                        offlineSale.localSaleId
                );


            // Save immediately after each success.
            saveOdropOfflineSalesQueue();
        }


    } catch (error) {

        console.error(
            'BRICK 1G — Unexpected sync error:',
            error
        );


    } finally {

        odropOfflineSaleSyncRunning =
            false;


        console.log(
            'BRICK 1G — Offline sales sync finished.'
        );
    }
}


// =========================================
// BRICK 1G — SYNC WHEN INTERNET RETURNS
// =========================================

window.addEventListener(
    'online',
    () => {

        console.log(
            'BRICK 1G — Internet connection restored.'
        );

        syncOdropOfflineSales();

    }
);


