// =========================================
// BRICK SELL 2 — RENDER SELL PRODUCTS
// =========================================

function renderSellProducts() {

    if (!sellProductGrid) {
        return;
    }


    const searchTerm =
        sellProductSearch
            ? sellProductSearch.value
                .toLowerCase()
                .trim()
            : '';


    const activeCategory =
        sellCategories
            ? sellCategories.querySelector(
                '.sell-category-btn.active'
            )
            : null;


    const selectedCategory =
        activeCategory
            ? activeCategory.getAttribute(
                'data-category'
            )
            : 'all';


    const visibleProducts =
        sellProducts.filter(product => {

            const title =
                String(
                    product.title || ''
                ).toLowerCase();


            const category =
                String(
                    product.category || ''
                );


            const matchesSearch =
                title.includes(searchTerm);


            const matchesCategory =
                selectedCategory === 'all' ||
                category === selectedCategory;


            return (
                matchesSearch &&
                matchesCategory
            );

        });


    // Update product count

    if (sellProductsCount) {

        sellProductsCount.textContent =
            `${visibleProducts.length} ${
                visibleProducts.length === 1
                    ? 'product'
                    : 'products'
            }`;

    }


    // No products

    if (visibleProducts.length === 0) {

        sellProductGrid.innerHTML = `

            <div class="sell-empty-state">

                <i class="fa-solid fa-box-open"></i>

                <strong>
                    No products found
                </strong>

                <span>
                    Try another search or category.
                </span>

            </div>

        `;

        return;
    }

    // Render products

    sellProductGrid.innerHTML =
        visibleProducts.map(product => {

            const stock =
                Number(product.stock || 0);


            const price =
                Number(product.price || 0);


            return `

                <div
                    class="sell-product-card"
                    data-product-id="${product.id}"
                >

                    <div class="sell-product-image">

                        ${
                            product.image

                            ? `
                                <img
                                    src="${product.image}"
                                    alt="${product.title || 'Product'}"
                                >
                            `

                            : `
                                <span>
                                    ${product.emoji || '📦'}
                                </span>
                            `
                        }

                    </div>


                    <div class="sell-product-info">

                        <strong>
                            ${product.title || 'Untitled Product'}
                        </strong>


                        <span>
                            ${formatCurrency(price)}
                        </span>


                        <small>
                            Stock: ${stock}
                        </small>

                    </div>


                    ${
                        stock > 0

                        ? `
                            <button
                                type="button"
                                class="sell-decrease-btn"
                                data-product-id="${product.id}"
                                aria-label="Sell ${product.title}"
                            >
                                <i class="fa-solid fa-minus"></i>
                            </button>
                        `

                        : `
                            <span class="sell-out-of-stock">
                                Out of stock
                            </span>
                        `
                    }

                </div>

            `;

        }).join('');

    console.log(
    'BRICK SELL 3 — Products rendered:',
    sellProducts.length
);

}

// =========================================
// BRICK SELL 5 — SELL PRODUCT DECREASE
// =========================================

if (sellProductGrid) {

    sellProductGrid.addEventListener(
        'click',
        (event) => {

            const decreaseButton =
                event.target.closest(
                    '.sell-decrease-btn'
                );

            if (!decreaseButton) {
                return;
            }


            const productId =
    decreaseButton.getAttribute(
        'data-product-id'
    );


           const product =
    sellProducts.find(
        item =>
            String(item.id) === String(productId)
    ); 


            if (!product) {

                console.error(
                    'BRICK SELL 5 — Product not found:',
                    productId
                );

                return;
            }


            const currentStock =
                Number(product.stock || 0);

            // Do not allow selling unavailable stock
            if (currentStock <= 0) {

                console.log(
                    'BRICK SELL 5 — Product is out of stock:',
                    product.title
                );

                return;
            }


            // =====================================
            // REDUCE AVAILABLE STOCK
            // =====================================

            product.stock =
                currentStock - 1;

             checkStockAlert(
                product,
                currentStock
            );
          
            // =====================================
            // FIND PRODUCT IN CURRENT SALE
            // =====================================

            const existingCartItem =
                currentSaleItems.find(
                item =>
             String(item.productId) === String(productId)
            );


            if (existingCartItem) {

                existingCartItem.quantity += 1;

            } else {

                currentSaleItems.push({

                    productId:
                        product.id,

                    title:
                        product.title || '',

                    price:
                        Number(product.price || 0),

                    costPrice:
    product.cost_price !== '' && product.cost_price != null
        ? Number(product.cost_price)
        : null,

                    image:
                        product.image || '',

                    emoji:
                        product.emoji || '📦',

                    quantity:
                        1

                });

            }


            console.log(
                'BRICK SELL 5 — Product added to current sale:',
                product
            );


            console.log(
                'BRICK SELL 5 — Current sale:',
                currentSaleItems
            );


            // Refresh product stock display
            renderSellProducts();


            // Refresh current sale
            renderSellCart();

        }
    );

}

// =========================================
// BRICK INBOX 7 — STOCK ALERT CHECK
// =========================================

async function checkStockAlert(
    product,
    oldStock
) {

    const newStock =
        Number(product.stock || 0);


    // OUT OF STOCK

    if (
        newStock === 0 &&
        oldStock > 0
    ) {

        await createNotification({

            type:
                'inventory',

            title:
                'Out of stock',

            message:
                `${product.title} is now out of stock.`,

            icon:
                'fa-solid fa-box-open'

        });


        console.log(
            'BRICK INBOX 7 — Out of stock:',
            product.title
        );

    }


    // LOW STOCK

    else if (
        newStock <= 3 &&
        oldStock > 3
    ) {


        await createNotification({

            type:
                'inventory',

            title:
                'Low stock alert',

            message:
                `${product.title} only has ${newStock} units remaining.`,

            icon:
                'fa-solid fa-triangle-exclamation'

        });


        console.log(
            'BRICK INBOX 7 — Low stock:',
            product.title,
            newStock
        );

    }

}


