// =========================================
// BRICK SELL 7 — CALCULATE SELL TOTALS
// =========================================

function updateSellTotals() {

    // =====================================
    // CALCULATE ITEMS
    // =====================================

    const totalItems =
        currentSaleItems.reduce(
            (total, item) => {

                return total +
                    Number(item.quantity || 0);

            },
            0
        );


    // =====================================
    // CALCULATE SUBTOTAL
    // =====================================

    const subtotal =
        currentSaleItems.reduce(
            (total, item) => {

                const price =
                    Number(item.price || 0);

                const quantity =
                    Number(item.quantity || 0);

                return total +
                    (price * quantity);

            },
            0
        );


    // =====================================
    // DISCOUNT
    // =====================================

    const discount =
        Number(sellDiscountAmount || 0);


    // =====================================
    // TAX
    // =====================================

    const tax =
        Number(sellTaxAmount || 0);


    // =====================================
    // GRAND TOTAL
    // =====================================

    const grandTotal =
        Math.max(
            0,
            subtotal -
            discount +
            tax
        );


    // =====================================
    // UPDATE ITEMS
    // =====================================

    if (sellTotalItems) {

        sellTotalItems.textContent =
            totalItems;

    }


    // =====================================
    // UPDATE SUBTOTAL
    // =====================================

    if (sellSubtotal) {

        sellSubtotal.textContent =
    formatCurrency(subtotal);

    }


    // =====================================
    // UPDATE DISCOUNT
    // =====================================

    if (sellDiscount) {

        sellDiscount.textContent =
    formatCurrency(discount);

    }


    // =====================================
    // UPDATE TAX
    // =====================================

    if (sellTax) {

        sellTax.textContent =
    formatCurrency(tax);

    }


    // =====================================
    // UPDATE GRAND TOTAL
    // =====================================

    if (sellGrandTotal) {

        sellGrandTotal.textContent =
    formatCurrency(grandTotal);

    }


    // =====================================
    // UPDATE PAY BUTTON
    // =====================================

    if (sellPayAmount) {

        sellPayAmount.textContent =
    formatCurrency(grandTotal);

    }


    // =====================================
    // DEBUG
    // =====================================

    console.log(
        'BRICK SELL 7 — Sell totals updated:',
        {
            items: totalItems,
            subtotal: subtotal,
            discount: discount,
            tax: tax,
            total: grandTotal
        }
    );

}


