/* =========================================
   BRICK 3 — SALES PERIOD DATE BOUNDARIES
   Date calculation only; no sales queries.
========================================= */

function getSalesPeriodRange(period, now = new Date()) {

    // Use local calendar dates for the seller's device.
    const today = new Date(now);

    today.setHours(0, 0, 0, 0);

    // Exclusive end boundary: midnight tomorrow.
    const endDate = new Date(today);

    endDate.setDate(endDate.getDate() + 1);

    // All time has no lower or upper date restriction.
    if (period === 'all') {
        return {
            startDate: null,
            endDate: null
        };
    }

    // Custom range will be handled in Brick 7.
    if (period === 'custom') {
        return {
            startDate: null,
            endDate: null
        };
    }

    let startDate = new Date(today);

    if (period === 'today') {
        // Start at midnight today.
    }

    else if (period === 'week') {
        // Monday is the first day of the week.
        const day = startDate.getDay();

        const daysSinceMonday = (day + 6) % 7;

        startDate.setDate(
            startDate.getDate() - daysSinceMonday
        );
    }

    else if (period === 'month') {
        startDate.setDate(1);
    }

    else if (
        period === 'last3' ||
        period === 'last6' ||
        period === 'last12'
    ) {
        const monthsBack = {
            last3: 3,
            last6: 6,
            last12: 12
        }[period];

        const originalDay = startDate.getDate();

        // Move to the first day to avoid month overflow.
        startDate.setDate(1);

        startDate.setMonth(
            startDate.getMonth() - monthsBack
        );

        // Restore the day, clamping to the target month's
        // final day when necessary.
        const lastDayOfTargetMonth = new Date(
            startDate.getFullYear(),
            startDate.getMonth() + 1,
            0
        ).getDate();

        startDate.setDate(
            Math.min(originalDay, lastDayOfTargetMonth)
        );
    }

    else if (period === 'year') {
        startDate = new Date(
            today.getFullYear(),
            0,
            1
        );
    }

    else {
        console.warn(
            'BRICK 3 — Unknown sales period:',
            period
        );

        return null;
    }

    return {
        startDate,
        endDate
    };
}

// =========================================
// GLOBAL SALES DATA LOADER
// =========================================
async function loadSellerSales(period = 'month') {

        // Wait until the seller's session has been restored.
    const user = await window.NEXODRA_AUTH_GATE.wait();

    // Safety check: never load sales without an authenticated seller.
    if (!user || !user.id) {
        console.warn(
            'SALES LOADER — Authentication gate returned no seller.'
        );
        return [];
    }

    console.log(
        'SALES LOADER — Authenticated seller ready:',
        user.id
    );

    // Custom range will be implemented in Brick 7.
    if (period === 'custom') {
        console.warn(
            'SALES LOADER — Custom range is not implemented yet.'
        );
        return [];
    }

    // Use Brick 3 to calculate the selected period.
    const range = getSalesPeriodRange(period);

    if (!range) {
        console.error(
            'SALES LOADER — Invalid sales period:',
            period
        );
        return [];
    }

    let query = supabaseClient
        .from('sales')
                .select(`
            id,
            owner_id,
            items,
            items_count,
            subtotal,
            discount,
            tax,
            total,
            customer_name,
            note,
            payment_method,
            created_at,
            updated_at
        `)
        .eq('owner_id', user.id);

    // All time has no date restrictions.
    if (range.startDate) {
        query = query.gte(
            'created_at',
            range.startDate.toISOString()
        );
    }

    // Exclude tomorrow and all future dates for bounded periods.
    if (range.endDate) {
        query = query.lt(
            'created_at',
            range.endDate.toISOString()
        );
    }

    const {
        data,
        error
    } = await query.order(
        'created_at',
        {
            ascending: false
        }
    );

    if (error) {
        console.error(
            'SALES LOADER ERROR:',
            error
        );
        return [];
      
    }

        // =========================================
    // SALES-1E — MERGE FULL SALES INTO CACHE
    // =========================================

    const fetchedSales = data || [];

    const cachedSales =
        loadNexodraSalesCache(user.id);

    const mergedSales = [
        ...fetchedSales,
        ...cachedSales.filter(cachedSale =>
            !fetchedSales.some(fetchedSale =>
                String(fetchedSale.id) ===
                String(cachedSale.id)
            )
        )
    ];

    const cacheSaved =
        saveNexodraSalesCache(
            user.id,
            mergedSales
        );

    // SALES-1G-G-B — TEST ALL-HISTORY INDEXEDDB

const historyCacheResult =
    await cacheAllSellerSales();

console.log(
    'SALES-1G-G-B — All-history test result:',
    historyCacheResult
);


    console.log(
        'SALES-1E — Bulk sales cache updated:',
        {
            fetched: fetchedSales.length,
            cachedBefore: cachedSales.length,
            cachedAfter: mergedSales.length,
            saved: cacheSaved
        }
    );

    console.log(
        'SALES LOADER — Period:',
        period,
        '| Loaded sales:',
        fetchedSales
    );

    return fetchedSales;
}

// =========================================
// SALES-1A — LOAD ONE SALE'S FULL DETAILS
// =========================================

function getNexodraCachedSale(userId, saleId) {

    const cachedSales =
        loadNexodraSalesCache(userId);

    return cachedSales.find(
        sale =>
            String(sale.id) === String(saleId)
    ) || null;
}



async function loadSaleDetails(saleId) {

    if (!saleId) {
        console.warn(
            'SALES-1A — No sale ID supplied.'
        );
        return null;
    }

    try {

                // Get the saved session from local storage.
        const {
            data: { session },
            error: sessionError
        } = await supabaseClient.auth.getSession();

        const user = session?.user || null;

        if (sessionError || !user) {
            console.error(
                'SALES-1E — No saved user session:',
                sessionError
            );
            return null;
        }

              // =====================================
// SALES-1G-H — CHECK INDEXEDDB FIRST
// =====================================

let cachedSale =
    await getNexodraSaleFromIndexedDB(
        user.id,
        saleId
    );

// Temporary legacy fallback while migration is verified.
if (!cachedSale) {
    cachedSale =
        getNexodraCachedSale(user.id, saleId);
}

if (cachedSale) {

    console.log(
        'SALES-1G-H — Sale found in local cache:',
        {
            saleId: cachedSale.id,
            source: cachedSale.cacheKey
                ? 'IndexedDB'
                : 'Legacy localStorage',
            products: Array.isArray(cachedSale.items)
                ? cachedSale.items.length
                : 0
        }
    );

    return cachedSale;
}

        console.log(
            'SALES-1E — Sale not cached; checking Supabase.'
        );

        // Fetch only this user's selected sale.
        const {
            data: sale,
            error: saleError
        } = await supabaseClient
            .from('sales')
            .select(`
                id,
                owner_id,
                items,
                items_count,
                subtotal,
                discount,
                tax,
                total,
                customer_name,
                note,
                payment_method,
                created_at,
                updated_at
            `)
            .eq('id', saleId)
            .eq('owner_id', user.id)
            .maybeSingle();

        if (saleError) {
            console.error(
                'SALES-1A — Sale details load failed:',
                saleError
            );
            return null;
        }

        if (!sale) {
            console.warn(
                'SALES-1A — Sale not found for this account:',
                saleId
            );
            return null;
        }

      
        // =====================================
        // SALES-1D — SAVE FULL SALE LOCALLY
        // =====================================

        const cachedSales =
            loadNexodraSalesCache(user.id);

        // Replace an older copy of this sale.
        const updatedCachedSales = [
            sale,
            ...cachedSales.filter(
                cachedSale =>
                    String(cachedSale.id) !==
                    String(sale.id)
            )
        ];

        const cacheSaved =
            saveNexodraSalesCache(
                user.id,
                updatedCachedSales
            );

        console.log(
            'SALES-1D — Sale cached:',
            {
                saleId: sale.id,
                saved: cacheSaved
            }
        );


        console.log(
            'SALES-1A — Sale details loaded:',
            {
                saleId: sale.id,
                itemsCount: sale.items_count,
                total: sale.total,
                customer: sale.customer_name,
                paymentMethod: sale.payment_method,
                products: Array.isArray(sale.items)
                    ? sale.items.length
                    : 0
            }
        );

        return sale;

    } catch (error) {

        console.error(
            'SALES-1A — Unexpected error:',
            error
        );

        return null;
    }
}


