// BRICK SALES OVERVIEW 3 — SALES HISTORY
// =========================================

function renderSalesHistory(sales) {

    const salesHistoryList =
        document.getElementById(
            'salesHistoryList'
        );


    if (!salesHistoryList) {

        console.error(
            'SALES OVERVIEW 3 — salesHistoryList not found.'
        );

        return;
    }    

  
    // =====================================
    // NO SALES
    // =====================================

    if (!sales || sales.length === 0) {

        salesHistoryList.innerHTML = `

            <div class="sales-history-empty">

                <i class="fa-solid fa-receipt"></i>

                <strong>
                    No sales yet
                </strong>

                <span>
                    Completed sales will appear here.
                </span>

            </div>

        `;

        console.log(
            'SALES OVERVIEW 3 — No sales to display.'
        );

        return;
    }


    // =====================================
    // RENDER SALES
    // =====================================

    salesHistoryList.innerHTML =
        sales.map(sale => {

            const saleTotal =
                Number(
                    sale.total || 0
                );


            const itemsCount =
                Number(
                    sale.items_count || 0
                );


            const saleDate =
                new Date(
                    sale.created_at
                );


            const formattedDate =
                saleDate.toLocaleDateString(
                    undefined,
                    {
                        day: 'numeric',
                        month: 'short',
                        year: 'numeric'
                    }
                );


            const formattedTime =
                saleDate.toLocaleTimeString(
                    undefined,
                    {
                        hour: '2-digit',
                        minute: '2-digit'
                    }
                );


            return `

                <div
                    class="sales-history-item"
                    data-sale-id="${sale.id}"
                >

                    <div class="sales-history-icon">

                        <i class="fa-solid fa-receipt"></i>

                    </div>


                    <div class="sales-history-info">

                        <strong>
                            Sale #${String(sale.id).slice(0, 8)}
                        </strong>

                        <span>
                            ${formattedDate}
                            ·
                            ${formattedTime}
                        </span>

                        <small>
                            ${itemsCount}
                            ${
                                itemsCount === 1
                                    ? 'item'
                                    : 'items'
                            }
                        </small>

                    </div>


                    <strong class="sales-history-total">
    ${formatCurrency(saleTotal)}
</strong>

                </div>

            `;

        }).join('');


    console.log(
        'SALES OVERVIEW 3 — Sales history rendered:',
        sales.length
    );

}

// =========================================
// SALES-1B — CLICK A SALE TO LOAD ITS DETAILS
// =========================================

(function setupSalesHistoryClick() {

    const salesHistoryList =
        document.getElementById('salesHistoryList');

    if (!salesHistoryList) {
        console.warn(
            'SALES-1B — Sales history list not found.'
        );
        return;
    }

    // Prevent duplicate listeners.
    if (salesHistoryList.dataset.detailsClickReady === 'true') {
        return;
    }

    salesHistoryList.dataset.detailsClickReady = 'true';

    salesHistoryList.addEventListener('click', async function(event) {

        const saleCard = event.target.closest(
            '.sales-history-item[data-sale-id]'
        );

        if (!saleCard || !salesHistoryList.contains(saleCard)) {
            return;
        }

        const saleId = saleCard.dataset.saleId;

        const sale = await loadSaleDetails(saleId);

        if (!sale) {
            alert('Could not load this sale. Please try again.');
            return;
        }

        const productLines = Array.isArray(sale.items)
            ? sale.items.length
            : 0;

        alert(
            'SALE DETAILS LOADED\n\n' +
            'Customer: ' + (sale.customer_name || 'Walk-in Customer') + '\n' +
            'Payment: ' + (sale.payment_method || 'Not specified') + '\n' +
            'Product lines: ' + productLines + '\n' +
            'Items count: ' + sale.items_count + '\n' +
            'Total: ' + sale.total
        );

    });

    console.log(
        'SALES-1B — Sale history click listener ready.'
    );

})();

// =========================================
// BRICK SALES OVERVIEW 4 — REVENUE LINE GRAPH
// =========================================

function renderSalesGraph(sales) {

    console.log(
        'SALES OVERVIEW 4 — GRAPH FUNCTION STARTED',
        sales
    );


    const graphContainer =
        document.getElementById(
            'salesGraph'
        );


    if (!graphContainer) {

        console.error(
            'SALES OVERVIEW 4 — salesGraph not found.'
        );

        return;
    }


    // =====================================
    // PREPARE 7 DAYS
    // =====================================

    const days = [];

    const today =
        new Date();

    today.setHours(
        0,
        0,
        0,
        0
    );


    for (
        let i = 6;
        i >= 0;
        i--
    ) {

        const date =
            new Date(today);

        date.setDate(
            today.getDate() - i
        );


        days.push({
            date: date,
            label: date.toLocaleDateString(
                'en-US',
                {
                    weekday: 'short'
                }
            ),
            revenue: 0
        });

    }


    // =====================================
    // ADD SALES TO EACH DAY
    // =====================================

    (sales || []).forEach(
        sale => {

            const saleDate =
                new Date(
                    sale.created_at
                );


            const saleDay =
                saleDate.toDateString();


            const matchingDay =
                days.find(
                    day =>
                        day.date.toDateString() ===
                        saleDay
                );


            if (matchingDay) {

                matchingDay.revenue +=
                    Number(
                        sale.total || 0
                    );

            }

        }
    );


    // =====================================
    // FIND MAX REVENUE
    // =====================================

    const maxRevenue =
        Math.max(
            ...days.map(
                day =>
                    day.revenue
            ),
            0
        );


    const graphMax =
        maxRevenue > 0
            ? maxRevenue
            : 1;


    // =====================================
    // GRAPH DIMENSIONS
    // =====================================

    const width = 700;
    const height = 260;

    const paddingLeft = 20;
    const paddingRight = 20;
    const paddingTop = 20;
    const paddingBottom = 45;


    const chartWidth =
        width -
        paddingLeft -
        paddingRight;


    const chartHeight =
        height -
        paddingTop -
        paddingBottom;


    // =====================================
    // CREATE POINTS
    // =====================================

    const points =
        days.map(
            (day, index) => {

                const x =
                    paddingLeft +
                    (
                        index /
                        (days.length - 1)
                    ) *
                    chartWidth;


                const y =
                    paddingTop +
                    chartHeight -
                    (
                        day.revenue /
                        graphMax
                    ) *
                    chartHeight;


                return {
                    x: x,
                    y: y,
                    revenue:
                        day.revenue,
                    label:
                        day.label
                };

            }
        );


        // =====================================
    // SMOOTH LINE PATH
    // =====================================

    let linePath = '';

    points.forEach(
        (point, index) => {

            if (index === 0) {

                linePath +=
                    `M ${point.x} ${point.y}`;

                return;

            }


            const previous =
                points[index - 1];


            const controlX =
                (
                    previous.x +
                    point.x
                ) / 2;


            linePath +=
                ` C ${controlX} ${previous.y},
                  ${controlX} ${point.y},
                  ${point.x} ${point.y}`;

        }
    );


    // =====================================
    // SMOOTH AREA UNDER LINE
    // =====================================

    const areaPath =
        linePath +
        ` L ${points[points.length - 1].x} ${height - paddingBottom}` +
        ` L ${points[0].x} ${height - paddingBottom}` +
        ` Z`;


    // =====================================
    // DAY LABELS
    // =====================================

    const labels =
        points.map(
            point => {

                return `
                    <text
                        x="${point.x}"
                        y="${height - 12}"
                        text-anchor="middle"
                        class="sales-graph-day"
                    >
                        ${point.label}
                    </text>
                `;

            }
        ).join('');


    // =====================================
    // DATA POINTS
    // =====================================

    const circles =
        points.map(
            point => {

                return `
                    <circle
                        cx="${point.x}"
                        cy="${point.y}"
                        r="5"
                        class="sales-graph-point"
                    >
                        <title>
    ${point.label}: ${formatCurrency(point.revenue)}
</title>
                    </circle>
                `;

            }
        ).join('');


    // =====================================
    // DRAW GRAPH
    // =====================================

    graphContainer.innerHTML = `

        <div class="sales-line-chart">

            <svg
                class="sales-line-chart-svg"
                viewBox="0 0 ${width} ${height}"
                preserveAspectRatio="none"
                role="img"
                aria-label="Sales revenue for the last seven days"
            >

                <!-- Area -->

              <path
               d="${areaPath}"
              class="sales-graph-area"
               ></path>


                <!-- Baseline -->

                <line
                    x1="${paddingLeft}"
                    y1="${height - paddingBottom}"
                    x2="${width - paddingRight}"
                    y2="${height - paddingBottom}"
                    class="sales-graph-baseline"
                ></line>


                <!-- Revenue line -->

                     <path
                       d="${linePath}"
                    class="sales-graph-line"
                     fill="none"
                      ></path>


                <!-- Day labels -->

                ${labels}

            </svg>

        </div>

    `;


    console.log(
        'SALES OVERVIEW 4 — Revenue line graph rendered:',
        days
    );

}


// =========================================
// BRICK SELL 10 — TODAY'S SALES SUMMARY
// =========================================

async function loadSellTodaySummary() {

    const revenueElement =
        document.getElementById(
            'sellTodayRevenue'
        );


    const transactionsElement =
        document.getElementById(
            'sellTodayTransactions'
        );


    const itemsElement =
        document.getElementById(
            'sellTodayItems'
        );


    if (
        !revenueElement ||
        !transactionsElement ||
        !itemsElement
    ) {

        return;

    }


    // =====================================
    // GET AUTHENTICATED USER
    // =====================================

        // Wait until the seller's session has been restored.
    const user = await window.NEXODRA_AUTH_GATE.wait();

    // Safety check: require an authenticated seller.
    if (!user || !user.id) {
        console.warn(
            'BRICK SELL 10 — Authentication gate returned no seller.'
        );
        return;
    }

    console.log(
        'BRICK SELL 10 — Authenticated seller ready:',
        user.id
    );


    // =====================================
    // GET START OF TODAY
    // =====================================

    const today =
        new Date();


    today.setHours(
        0,
        0,
        0,
        0
    );


    const tomorrow =
        new Date(today);


    tomorrow.setDate(
        tomorrow.getDate() + 1
    );


    const todayStart =
        today.toISOString();


    const tomorrowStart =
        tomorrow.toISOString();


    // =====================================
    // LOAD TODAY'S SALES
    // =====================================

    const {
        data: sales,
        error: salesError
    } =
        await supabaseClient
            .from('sales')
            .select(
                'id, items_count, total, created_at'
            )
            .eq(
                'owner_id',
                user.id
            )
            .gte(
                'created_at',
                todayStart
            )
            .lt(
                'created_at',
                tomorrowStart
            );


    if (salesError) {

        console.error(
            'BRICK SELL 10 — Could not load today sales:',
            salesError
        );

        return;

    }


    // =====================================
    // CALCULATE SUMMARY
    // =====================================

    const transactions =
        sales.length;


    const itemsSold =
        sales.reduce(
            (total, sale) => {

                return total +
                    Number(
                        sale.items_count || 0
                    );

            },
            0
        );


    const revenue =
        sales.reduce(
            (total, sale) => {

                return total +
                    Number(
                        sale.total || 0
                    );

            },
            0
        );


    // =====================================
    // UPDATE UI
    // =====================================

    revenueElement.textContent =
    formatCurrency(revenue);


    transactionsElement.textContent =
        transactions;


    itemsElement.textContent =
        itemsSold;


    console.log(
        'BRICK SELL 10 — Today summary:',
        {
            revenue: revenue,
            transactions: transactions,
            itemsSold: itemsSold
        }
    );

}


// =========================================
// LOAD TODAY'S SELL SUMMARY
// =========================================

loadSellTodaySummary();

  
