// =========================================
// CALCULATOR LOGIC
// BRICK CALC 4
// =========================================

const calculatorExpression =
    document.getElementById(
        'calculatorExpression'
    );

const calculatorResult =
    document.getElementById(
        'calculatorResult'
    );

const calculatorKeys =
    document.querySelectorAll(
        '.calculator-key'
    );


let calculatorCurrentValue = '0';
let calculatorStoredValue = null;
let calculatorOperator = null;
let calculatorWaitingForValue = false;
let calculatorJustCalculated = false;


// =========================================
// UPDATE DISPLAY
// =========================================

function updateCalculatorDisplay() {

    if (calculatorExpression) {

        calculatorExpression.textContent =
            calculatorOperator
                ? `${calculatorStoredValue ?? calculatorCurrentValue} ${calculatorOperator}`
                : calculatorCurrentValue;

    }


    if (calculatorResult) {

        calculatorResult.textContent =
            calculatorCurrentValue;

    }

}


// =========================================
// INPUT NUMBER
// =========================================

function calculatorInputNumber(value) {

    if (calculatorWaitingForValue || calculatorJustCalculated) {

        calculatorCurrentValue =
            value === '.'
                ? '0.'
                : value;

        calculatorWaitingForValue = false;
        calculatorJustCalculated = false;

        updateCalculatorDisplay();

        return;

    }


    if (value === '.') {

        if (
            calculatorCurrentValue
                .includes('.')
        ) {
            return;
        }

        calculatorCurrentValue += '.';

    } else {

        if (
            calculatorCurrentValue === '0'
        ) {

            calculatorCurrentValue =
                value;

        } else {

            calculatorCurrentValue += value;

        }

    }


    updateCalculatorDisplay();

}


// =========================================
// CHOOSE OPERATOR
// =========================================

function calculatorChooseOperator(
    operator
) {

    const current =
        Number(
            calculatorCurrentValue
        );


    if (
        calculatorStoredValue !== null &&
        calculatorOperator &&
        !calculatorWaitingForValue
    ) {

        const result =
            calculateCalculatorResult(
                calculatorStoredValue,
                current,
                calculatorOperator
            );

        calculatorStoredValue =
            result;

        calculatorCurrentValue =
            String(result);

    } else {

        calculatorStoredValue =
            current;

    }


    calculatorOperator =
        operator;

    calculatorWaitingForValue =
        true;

    calculatorJustCalculated =
        false;

    updateCalculatorDisplay();

}


// =========================================
// CALCULATE
// =========================================

function calculateCalculatorResult(
    first,
    second,
    operator
) {

    switch (operator) {

        case '+':
            return first + second;

        case '-':
            return first - second;

        case '*':
            return first * second;

        case '/':
            if (second === 0) {
                return null;
            }

            return first / second;

        default:
            return second;

    }

}


// =========================================
// EQUALS
// =========================================

function calculatorEquals() {

    if (
        calculatorStoredValue === null ||
        !calculatorOperator
    ) {
        return;
    }


    const first =
        Number(
            calculatorStoredValue
        );

    const second =
        Number(
            calculatorCurrentValue
        );


    const result =
        calculateCalculatorResult(
            first,
            second,
            calculatorOperator
        );


    if (result === null) {

        calculatorCurrentValue =
            'Error';

        calculatorStoredValue =
            null;

        calculatorOperator =
            null;

        calculatorWaitingForValue =
            true;

        calculatorJustCalculated =
            true;

        updateCalculatorDisplay();

        return;

    }


    calculatorCurrentValue =
        String(result);

    calculatorStoredValue =
        null;

    calculatorOperator =
        null;

    calculatorWaitingForValue =
        false;

    calculatorJustCalculated =
        true;

    updateCalculatorDisplay();

}


// =========================================
// CLEAR
// =========================================

function calculatorClear() {

    calculatorCurrentValue =
        '0';

    calculatorStoredValue =
        null;

    calculatorOperator =
        null;

    calculatorWaitingForValue =
        false;

    calculatorJustCalculated =
        false;

    updateCalculatorDisplay();

}


// =========================================
// DELETE LAST DIGIT
// =========================================

function calculatorDelete() {

    if (
        calculatorWaitingForValue ||
        calculatorJustCalculated
    ) {
        return;
    }


    if (
        calculatorCurrentValue.length <= 1
    ) {

        calculatorCurrentValue =
            '0';

    } else {

        calculatorCurrentValue =
            calculatorCurrentValue.slice(
                0,
                -1
            );

    }


    updateCalculatorDisplay();

}


// =========================================
// PERCENT
// =========================================

function calculatorPercent() {

    const value =
        Number(
            calculatorCurrentValue
        );


    if (!Number.isFinite(value)) {
        return;
    }


    calculatorCurrentValue =
        String(value / 100);

    updateCalculatorDisplay();

}


// =========================================
// BUTTON EVENTS
// =========================================

calculatorKeys.forEach(
    button => {

        button.addEventListener(
            'click',
            () => {

                const value =
                    button.getAttribute(
                        'data-calculator-value'
                    );

                const action =
                    button.getAttribute(
                        'data-calculator-action'
                    );


                if (value !== null) {

                    if (
                        value === '+' ||
                        value === '-' ||
                        value === '*' ||
                        value === '/'
                    ) {

                        calculatorChooseOperator(
                            value
                        );

                    } else {

                        calculatorInputNumber(
                            value
                        );

                    }

                    return;

                }


                switch (action) {

                    case 'clear':
                        calculatorClear();
                        break;

                    case 'delete':
                        calculatorDelete();
                        break;

                    case 'percent':
                        calculatorPercent();
                        break;

                    case 'equals':
                        calculatorEquals();
                        break;

                }

            }
        );

    }
);


// =========================================
// INITIAL DISPLAY
// =========================================

updateCalculatorDisplay();

