// =========================================
// C6-D — CENTRAL CURRENCY FORMATTER
// =========================================

function formatCurrency(
    amount,
    currencyCode = currentCurrencyCode
) {

    // =====================================
    // NORMALIZE AMOUNT
    // =====================================

    const numericAmount =
        Number(amount);


    const safeAmount =
        Number.isFinite(
            numericAmount
        )
            ? numericAmount
            : 0;


    // =====================================
    // NORMALIZE CURRENCY
    // =====================================

    const safeCurrency =
        String(
            currencyCode ||
            'USD'
        )
            .trim()
            .toUpperCase();


    // =====================================
    // FORMAT CURRENCY
    // =====================================

    try {

        const formatter =
            new Intl.NumberFormat(
                currentLanguageCode || 'en',
                {
                    style:
                        'currency',

                    currency:
                        safeCurrency
                }
            );


        return formatter.format(
            safeAmount
        );


    } catch (error) {

        console.warn(
            'BRICK C6-D — Currency formatter fallback:',
            error
        );


        // =================================
        // SAFE FALLBACK
        // =================================

        return (
            safeCurrency +
            ' ' +
            safeAmount.toFixed(2)
        );

    }

}


