async function loadSellerOrders() {

    console.log(
        'BRICK ORDERS C4-A — Loading seller orders.'
    );

    try {

        // =====================================
        // GET CURRENT SELLER
        // =====================================

        const {
            data: {
                user
            },
            error: userError
        } =
            await supabaseClient.auth.getUser();


        if (userError || !user) {

            console.error(
                'BRICK ORDERS C4-A — Seller authentication failed:',
                userError
            );

            return [];

        }


        console.log(
            'BRICK ORDERS C4-A — Seller:',
            user.id
        );


        // =====================================
        // FIND SELLER STORE
        // =====================================

        const {
            data: sellerStore,
            error: storeError
        } =
            await supabaseClient
                .from('stores')
                .select('id, owner_id')
                .eq(
                    'owner_id',
                    user.id
                )
                .maybeSingle();


        if (storeError) {

            console.error(
                'BRICK ORDERS C4-A — Store lookup failed:',
                storeError
            );

            return [];

        }


        if (!sellerStore) {

            console.warn(
                'BRICK ORDERS C4-A — Seller store not found.'
            );

            return [];

        }


        console.log(
            'BRICK ORDERS C4-A — Seller store:',
            sellerStore
        );

      console.log(
           'BRICK ORDERS C4-A — Store ID used for order query:',
          sellerStore.id
        );


        // =====================================
        // LOAD ORDERS
        // =====================================

        const {
            data: orders,
            error: ordersError
        } =
            await supabaseClient
                .from('orders')
                .select(`
                    id,
                    store_id,
                    customer_id,
                    customer_name,
                    customer_phone,
                    delivery_address,
                    city,
                    customer_notes,
                    payment_method,
                    total_amount,
                    status,
                    created_at,
                    updated_at
                `)
                .eq(
                    'store_id',
                     sellerStore.id
                 )
                .neq(
                    'status',
                   'cancelled'
                 )
                .order(
                    'created_at',
                    {
                        ascending: false
                    }
                );


        if (ordersError) {

            console.error(
                'BRICK ORDERS C4-A — Orders query failed:',
                ordersError
            );

            return [];

        }


        console.log(
            'BRICK ORDERS C4-A — Orders loaded successfully:',
            orders
        );

      console.log(
            'BRICK ORDERS C4-A — Raw orders query result:',
            orders
        );


        return orders || [];


    } catch (error) {

        console.error(
            'BRICK ORDERS C4-A — Unexpected error:',
            error
        );

        return [];

    }

}


/* =========================================
   NEXODRA — DASHBOARD PENDING ORDERS
   C4-G — CACHE + AUTO REFRESH
========================================= */

(function initPendingOrdersOverview() {

    'use strict';

    const ordersCardValue =
        document.getElementById('overviewOrders');

    if (!ordersCardValue) {
        console.warn(
            'C4-G — overviewOrders element not found.'
        );
        return;
    }

    let ordersCacheKey = null;

    // -----------------------------------------
    // GET CACHE KEY FOR CURRENT SELLER
    // -----------------------------------------

    async function getOrdersCacheKey() {

        try {

            const {
                data: {
                    user
                },
                error
            } = await supabaseClient.auth.getUser();

            if (error || !user) {
                return null;
            }

            return 'nexodra_orders_cache_' + user.id;

        } catch (error) {

            console.error(
                'C4-G — Could not identify seller:',
                error
            );

            return null;

        }

    }

    // -----------------------------------------
    // READ CACHED ORDERS
    // -----------------------------------------

    function readCachedOrders() {

        if (!ordersCacheKey) {
            return [];
        }

        try {

            const cached =
                localStorage.getItem(
                    ordersCacheKey
                );

            if (!cached) {
                return [];
            }

            const parsed =
                JSON.parse(cached);

            if (!Array.isArray(parsed)) {
                return [];
            }

            return parsed;

        } catch (error) {

            console.error(
                'C4-G — Could not read cached orders:',
                error
            );

            return [];

        }

    }

    // -----------------------------------------
    // COUNT PENDING ORDERS
    // -----------------------------------------

    function countPendingOrders(orders) {

        if (!Array.isArray(orders)) {
            return 0;
        }

        return orders.filter(order => {

            const status =
                String(order.status || '')
                    .trim()
                    .toLowerCase();

            return status === 'pending';

        }).length;

    }

    // -----------------------------------------
    // UPDATE DASHBOARD CARD
    // -----------------------------------------

    function renderPendingOrdersCount(orders) {

        const pendingCount =
            countPendingOrders(orders);

        ordersCardValue.textContent =
            pendingCount.toLocaleString();

        console.log(
            'C4-G — Pending orders count:',
            pendingCount
        );

    }

    // -----------------------------------------
    // SAVE ORDERS CACHE
    // -----------------------------------------

    function saveCachedOrders(orders) {

        if (!ordersCacheKey) {
            return false;
        }

        if (!Array.isArray(orders)) {
            return false;
        }

        try {

            localStorage.setItem(
                ordersCacheKey,
                JSON.stringify(orders)
            );

            return true;

        } catch (error) {

            console.error(
                'C4-G — Could not cache orders:',
                error
            );

            return false;

        }

    }

    // -----------------------------------------
    // LOAD CACHE FIRST
    // -----------------------------------------

    async function initializeOrdersOverview() {

        ordersCacheKey =
            await getOrdersCacheKey();

        if (!ordersCacheKey) {

            console.warn(
                'C4-G — Seller not authenticated.'
            );

            return;

        }

        // Display cached count immediately.
        const cachedOrders =
            readCachedOrders();

        renderPendingOrdersCount(
            cachedOrders
        );

        // -------------------------------------
        // REFRESH FROM SUPABASE
        // -------------------------------------

        if (!navigator.onLine) {

            console.log(
                'C4-G — Offline. Showing cached orders.'
            );

            return;

        }

        await refreshOrdersOverview();

    }

    // -----------------------------------------
    // REFRESH FROM SUPABASE
    // -----------------------------------------

    async function refreshOrdersOverview() {

        if (!navigator.onLine) {
            return;
        }

        try {

            console.log(
                'C4-G — Refreshing dashboard orders.'
            );

            const orders =
                await loadSellerOrders();

            if (!Array.isArray(orders)) {
                return;
            }

            // Cache the latest seller orders.
            saveCachedOrders(orders);

            // Update the dashboard count.
            renderPendingOrdersCount(
                orders
            );

            console.log(
                'C4-G — Dashboard orders refreshed.'
            );

        } catch (error) {

            console.error(
                'C4-G — Orders refresh failed:',
                error
            );

            // Keep the last cached count.
            renderPendingOrdersCount(
                readCachedOrders()
            );

        }

    }

    // -----------------------------------------
    // ONLINE EVENT
    // -----------------------------------------

    window.addEventListener(
        'online',
        function () {

            console.log(
                'C4-G — Device online. Refreshing orders.'
            );

            refreshOrdersOverview();

        }
    );

    // -----------------------------------------
    // REFRESH AFTER ORDER SCREEN LOAD
    // -----------------------------------------

    window.addEventListener(
        'nexodra:orders-updated',
        function () {

            refreshOrdersOverview();

        }
    );

    // -----------------------------------------
    // INITIALIZE
    // -----------------------------------------

    if (document.readyState === 'loading') {

        document.addEventListener(
            'DOMContentLoaded',
            initializeOrdersOverview,
            {
                once: true
            }
        );

    } else {

        initializeOrdersOverview();

    }

})();



