async function loadNotifications() {

    const notificationList =
        document.getElementById(
            'notificationList'
        );

    if (!notificationList) {
        return;
    }

    const {
        data: { user }
    } =
    await supabaseClient.auth.getUser();

    if (!user) {
        return;
    }

    const {
        data,
        error
    } =
    await supabaseClient
        .from('notifications')
        .select(`
            id,
            type,
            title,
            message,
            icon,
            read,
            created_at
        `)
        .eq(
            'user_id',
            user.id
        )
        .order(
            'created_at',
            {
                ascending: false
            }
        );

    if (error) {

        console.error(
            'NOTIFICATIONS LOAD ERROR:',
            error
        );

        return;
    }

    console.log(
    'NOTIFICATIONS LOADED:',
    data
);

window.notifications = data || [];

const filtered =
    filterNotificationCategories(
        window.notifications,
        activeNotificationCategory
    );

renderNotifications(
    filtered
);

updateNotificationUnreadCount(
    window.notifications
);

}
// =========================================
// BRICK INBOX 2 — RENDER NOTIFICATIONS
// =========================================

function renderNotifications(notifications) {

    const notificationList =
    document.getElementById(
        'notificationsCenterList'
    );


    if (!notificationList) {

        console.error(
            'BRICK INBOX 2 — notificationList not found.'
        );

        return;
    }


    // =====================================
    // EMPTY NOTIFICATIONS
    // =====================================

    if (
        !notifications ||
        notifications.length === 0
    ) {

        notificationList.innerHTML = `

            <div class="notification-empty">

                <div class="notification-empty-icon">
                    <i class="fa-regular fa-bell"></i>
                </div>

                <strong>
                    No notifications yet
                </strong>

                <span>
                    You're all caught up.
                </span>

            </div>

        `;

        return;
    }


    // =====================================
    // RENDER NOTIFICATIONS
    // =====================================

    notificationList.innerHTML =
        notifications.map(notification => {

            const notificationDate =
                notification.created_at
                    ? new Date(
                        notification.created_at
                    ).toLocaleString()
                    : '';


            return `

                <div
                    class="notification-item ${
                        notification.read
                            ? ''
                            : 'unread'
                    }"
                    data-notification-id="${notification.id}"
                >

                    <div class="notification-icon">

                        <i class="${
                            notification.icon ||
                            'fa-regular fa-bell'
                        }"></i>

                    </div>


                    <div class="notification-content">

                        <strong>
                            ${
                                notification.title ||
                                'Notification'
                            }
                        </strong>

                        <p>
                            ${
                                notification.message ||
                                ''
                            }
                        </p>

                        <small>
                            ${notificationDate}
                        </small>

                    </div>

                </div>

            `;

        }).join('');


    console.log(
        'BRICK INBOX 2 — Notifications rendered:',
        notifications
    );

}

