// =========================================
// BRICK INBOX 8 — CATEGORY FILTERS
// =========================================

let activeNotificationFilter = 'all';


function filterNotifications(
    notifications,
    filter
) {

        if (filter === 'all') {

        return notifications;

    }
  
    if (filter === 'unread') {

        return notifications.filter(
            notification =>
                notification.read === false
        );

    }



    if (filter === 'chat') {

        return notifications.filter(
            notification =>
                notification.type === 'chat'
        );

    }



    if (filter === 'pending') {

    return notifications.filter(
        notification =>
            notification.status === 'pending' ||
            notification.type === 'pending'
    );

}


if (filter === 'fulfilled') {

    return notifications.filter(
        notification =>
            notification.status === 'fulfilled' ||
            notification.type === 'fulfilled'
    );

}



    return notifications;

}


document.querySelectorAll(
    '[data-notification-filter]'
)
.forEach(button => {


    button.addEventListener(
        'click',
        () => {


            // =========================================
            // BRICK INBOX 8A — ACTIVE TAB UI STATE
            // =========================================

            document.querySelectorAll(
                '[data-notification-filter]'
            )
            .forEach(tab => {

                tab.classList.remove(
                    'active'
                );

            });


            button.classList.add(
                'active'
            );


            // =========================================
            // BRICK INBOX 8 — APPLY FILTER
            // =========================================

            activeNotificationFilter =
                button.dataset.notificationFilter;


            const filtered =
                filterNotifications(
                    window.notifications || [],
                    activeNotificationFilter
                );


            renderNotifications(
                filtered
            );


            console.log(
                'BRICK INBOX 8 — Filter applied:',
                activeNotificationFilter,
                filtered
            );

        }
    );


});

// =========================================
// NOTIFICATION CENTER CATEGORY FILTERS
// BRICK NOTIFICATION 1
// =========================================

let activeNotificationCategory = 'all';


function filterNotificationCategories(
    notifications,
    category
) {

    if (
        category === 'all'
    ) {

        return notifications;

    }


    return notifications.filter(
        notification => {

            const type =
                String(
                    notification.type || ''
                ).toLowerCase();


            switch (category) {

                case 'inventory':

                    return type === 'inventory';


                case 'sales':

                    return (
                        type === 'sale' ||
                        type === 'sales'
                    );


                case 'account':

                    return type === 'account';


                case 'store':

                    return type === 'store';


                case 'system':

                    return (
                        type === 'system' ||
                        type === 'general'
                    );


                default:

                    return false;

            }

        }
    );

}


// =========================================
// CATEGORY BUTTON EVENTS
// =========================================

document.querySelectorAll(
    '[data-notification-category]'
)
.forEach(button => {

    button.addEventListener(
        'click',
        () => {

            // Remove active state
            // from notification categories

            document.querySelectorAll(
                '[data-notification-category]'
            )
            .forEach(categoryButton => {

                categoryButton.classList.remove(
                    'active'
                );

            });


            // Activate clicked category

            button.classList.add(
                'active'
            );


            // Save selected category

            activeNotificationCategory =
                button.dataset.notificationCategory;


            // Filter current notifications

            const filtered =
                filterNotificationCategories(
                    window.notifications || [],
                    activeNotificationCategory
                );


            // Render filtered notifications

            renderNotifications(
                filtered
            );


            console.log(
                'BRICK NOTIFICATION 1 — Category applied:',
                activeNotificationCategory,
                filtered
            );

        }
    );

});


// =========================================
// BRICK INBOX 4 — UNREAD COUNT + MARK READ
// =========================================

function updateNotificationUnreadCount(
    notifications
) {

    const unreadText =
        document.getElementById(
            'notificationUnreadText'
        );


    if (!unreadText) {

        console.error(
            'BRICK INBOX 4 — notificationUnreadText not found.'
        );

        return;
    }


    const unreadCount =
        (notifications || []).filter(
            notification =>
                notification.read === false
        ).length;


    if (unreadCount === 0) {

        unreadText.textContent =
            'No unread notifications';

        return;
    }


    unreadText.textContent =
        unreadCount === 1
            ? '1 unread notification'
            : `${unreadCount} unread notifications`;


    console.log(
        'BRICK INBOX 4 — Unread notifications:',
        unreadCount
    );

}


// =========================================
// MARK ALL NOTIFICATIONS AS READ
// =========================================

async function markAllNotificationsRead() {

    const {
        data: {
            user
        },
        error: userError
    } =
        await supabaseClient.auth.getUser();


    if (userError || !user) {

        console.error(
            'BRICK INBOX 4 — User not found:',
            userError
        );

        return;
    }


    const {
        error
    } =
        await supabaseClient
            .from('notifications')
            .update({
                read: true
            })
            .eq(
                'user_id',
                user.id
            )
            .eq(
                'read',
                false
            );


    if (error) {

        console.error(
            'BRICK INBOX 4 — Could not mark notifications as read:',
            error
        );

        return;
    }


    console.log(
        'BRICK INBOX 4 — All notifications marked as read.'
    );


    // Refresh notification list
    await loadNotifications();

}

