    document.getElementById(
        'markNotificationsReadBtn'
    );


if (markNotificationsReadBtn) {

    markNotificationsReadBtn.addEventListener(
        'click',
        () => {

            markAllNotificationsRead();

        }
    );

}

// =========================================
// BRICK INBOX 5 — REAL-TIME NOTIFICATIONS
// =========================================

let notificationsChannel = null;


async function startNotificationsRealtime() {

    // =====================================
    // GET AUTHENTICATED USER
    // =====================================

    const {
        data: {
            user
        },
        error: userError
    } =
        await supabaseClient.auth.getUser();


    if (userError || !user) {

        console.error(
            'BRICK INBOX 5 — User not found:',
            userError
        );

        return;
    }


    // =====================================
    // PREVENT DUPLICATE CHANNELS
    // =====================================

    if (notificationsChannel) {

        console.log(
            'BRICK INBOX 5 — Realtime already running.'
        );

        return;
    }


    // =====================================
    // CREATE REALTIME CHANNEL
    // =====================================

    notificationsChannel =
        supabaseClient
            .channel(
                `notifications-${user.id}`
            )
            .on(
                'postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'notifications',
                    filter:
                        `user_id=eq.${user.id}`
                },
                async (payload) => {

                    console.log(
                        'BRICK INBOX 5 — New notification received:',
                        payload.new
                    );


                    // Reload notifications
                    // so the existing renderer
                    // stays the single source of UI truth.

                    await loadNotifications();

                }
            )
            .subscribe(
                (status, error) => {

                    console.log(
                        'BRICK INBOX 5 — Realtime status:',
                        status
                    );


                    if (
                        status ===
                            'CHANNEL_ERROR' ||
                        status ===
                            'TIMED_OUT'
                    ) {

                        console.error(
                            'BRICK INBOX 5 — Realtime error:',
                            error
                        );

                    }

                }
            );

}

startNotificationsRealtime();

// =========================================
// BRICK INBOX 3 — CREATE NOTIFICATION
// =========================================

async function createNotification({
    type = 'general',
    title = 'New Notification',
    message = '',
    icon = 'fa-regular fa-bell'
} = {}) {

    const {
        data: {
            user
        },
        error: userError
    } =
        await supabaseClient.auth.getUser();


    if (userError || !user) {

        console.error(
            'BRICK INBOX 3 — User not found:',
            userError
        );

        return false;
    }


    const {
        error
    } =
        await supabaseClient
            .from('notifications')
            .insert({

                user_id:
                    user.id,

                type:
                    type,

                title:
                    title,

                message:
                    message,

                icon:
                    icon,

                read:
                    false

            });


    if (error) {

        console.error(
            'BRICK INBOX 3 — Notification creation failed:',
            error
        );

        return false;
    }


    console.log(
        'BRICK INBOX 3 — Notification created:',
        {
            type,
            title,
            message
        }
    );


    return true;
}

