//
// id
// conversation_id
// sender_id
// receiver_id
// message
// read
// created_at
// =========================================

const chatPanel =
    document.getElementById(
        'chatPanel'
    );

const closeChatBtn =
    document.getElementById(
        'closeChatBtn'
    );

