/*
 * GitHub Pages Project Pages uses:
 *
 * /nexodra-seller-app/
 *
 * Internally the Nexodra router works with:
 *
 * /
 * /store/odro
 *
 * Therefore remove the project prefix before
 * the existing route detection runs.
 */

const APP_BASE_PATH =
    '/nexodra-seller-app';

const browserPath =
    window.location.pathname;

const currentPath =
    browserPath === APP_BASE_PATH
        ? '/'
        : browserPath.startsWith(
            APP_BASE_PATH + '/'
        )
            ? browserPath.slice(
                APP_BASE_PATH.length
            )
            : browserPath;

console.log(
    'ROUTING TEST — browser pathname:',
    browserPath
);

console.log(
    'ROUTING TEST — normalized pathname:',
    currentPath
);

console.log(
    'ROUTING TEST — href:',
    window.location.href
);


if (
    currentPath.startsWith('/store/')
) {

    currentPublicStoreSlug =
        currentPath
            .replace('/store/', '')
            .split('/')[0];

  isStorePreviewMode = false;

    console.log(
        'PUBLIC STORE — Slug detected:',
        currentPublicStoreSlug
    );

    showPublicStore();

}


// =========================================
// BRICK 3D — LOAD PRODUCTS FROM SUPABASE
// =========================================

async function loadProductsFromSupabase() {

  
    // =========================================
    // AUTH GATE — WAIT BEFORE LOADING PRODUCTS
    // =========================================

    const authenticatedSeller =
        await window.NEXODRA_AUTH_GATE.wait();

    if (!authenticatedSeller || !authenticatedSeller.id) {
        console.warn(
            'BRICK 3D — Product loading stopped: no authenticated seller.'
        );
        return;
    }

    console.log(
        'AUTH GATE — Loading products for seller:',
        authenticatedSeller.id
    );


    console.log(
        'BRICK 3D — Loading products from Supabase...'
    );

    // =========================================
    // C7-A — SHOW PRODUCT LOADING STATE
    // =========================================

    showProductLoadingState(
        productGrid,
        6
    );



    // =========================================
    // BRICK P1-C — AUTH + OFFLINE CACHE RESTORE
    // =========================================

    let user = null;
    let userError = null;

    // Try to get the authenticated user first.
    try {

        const authResult =
            await supabaseClient.auth.getUser();

        user = authResult.data?.user || null;
        userError = authResult.error || null;

    } catch (error) {

        userError = error;

    }

    // Use authenticated ID when available.
    // Otherwise, use the previously saved cache owner ID.
    let productCacheUserId = user?.id || null;

    if (!productCacheUserId) {

        try {

            productCacheUserId =
                localStorage.getItem(
                    'nexodraLastProductUserId'
                );

        } catch (error) {

            console.error(
                'BRICK P1-C — Could not read saved user ID:',
                error
            );

        }

    }

    // =========================================
    // BRICK P1-A — LOAD LOCAL PRODUCT CACHE
    // =========================================

    if (productCacheUserId) {

        const localProductsKey =
            'nexodraProducts_' + productCacheUserId;

        try {

            const savedLocalProducts =
                localStorage.getItem(
                    localProductsKey
                );

            if (savedLocalProducts) {

                const cachedProducts =
                    JSON.parse(savedLocalProducts);

                if (Array.isArray(cachedProducts)) {

                    products = cachedProducts;

                    console.log(
                        'BRICK P1-A — Local products loaded:',
                        products.length
                    );

                    renderProducts();

                    syncSellProducts();

                }

            } else {

                console.log(
                    'BRICK P1-C — No local product cache found.'
                );

            }

        } catch (error) {

            console.error(
                'BRICK P1-C — Could not restore local products:',
                error
            );

        }

    } else {

        console.warn(
            'BRICK P1-C — No saved product cache user ID.'
        );

    }

    // =========================================
    // BRICK P1-C — OFFLINE FALLBACK
    // =========================================

    if (userError || !user) {

        console.warn(
            'BRICK P1-C — Authentication unavailable; using local products.',
            userError
        );

        return;

    }

    // Continue the existing online flow.
    console.log(
        'BRICK 3D — Logged-in user ID:',
        user.id
    );

  

    // Load only this user's products
    const {
        data: supabaseProducts,
        error: productError
    } = await supabaseClient
        .from('products')
        .select('*')
        .eq('owner_id', user.id)
        .order('title');


    if (productError) {

        console.error(
            'BRICK 3D — Could not load products:',
            productError
        );

        return;
    }


    console.log(
        'BRICK 3D — Products loaded from Supabase:',
        supabaseProducts
    );


    // Replace the local product list with
// the authenticated user's Supabase products.
products = supabaseProducts || [];



    // =========================================
    // BRICK P1-B — SAVE LOCAL PRODUCT CACHE
    // =========================================

    try {

        localStorage.setItem(
            'nexodraProducts_' + user.id,
            JSON.stringify(products)
        );

        // BRICK P1-C — Remember product cache owner
        localStorage.setItem(
            'nexodraLastProductUserId',
            String(user.id)
        );

        console.log(
            'BRICK P1-B — Local product cache saved:',
            products.length
        );

        console.log(
            'BRICK P1-C — Product cache user ID saved:',
            user.id
        );

    } catch (error) {

        console.error(
            'BRICK P1-B/C — Could not save local product cache:',
            error
        );

    }


  
// =========================================
// BRICK S2-A — SYNC BARCODE CACHE
// =========================================

syncOdropBarcodeCache(
    products,
    user.id
);


// Keep the existing product interface working.
renderProducts();


// Sync the same products to the Sell page.
syncSellProducts();

}


// Run Brick 3D
loadProductsFromSupabase();

