    localStorage.getItem(
        'odropStoreTheme'
    ) || 'default';

// =========================================
// APPLY STORE THEME
// =========================================

function applyStoreTheme(
    theme
) {

    // Remove previous theme classes

    document.body.classList.remove(
        'store-theme-default',
        'store-theme-dark'
    );


    // Apply selected theme

    if (
        theme === 'dark'
    ) {

        document.body.classList.add(
            'store-theme-dark'
        );

    } else {

        document.body.classList.add(
            'store-theme-default'
        );

    }


    // Update selected button

    appearanceThemeOptions.forEach(
        option => {

            option.classList.remove(
                'active'
            );


            if (
                option.dataset.theme ===
                theme
            ) {

                option.classList.add(
                    'active'
                );

            }

        }
    );


    // Save selection

    selectedStoreTheme =
        theme;


    localStorage.setItem(
        'odropStoreTheme',
        theme
    );


    console.log(
        'Store theme applied:',
        theme
    );

}

// =========================================
// STORE THEME BUTTON EVENTS
// =========================================

appearanceThemeOptions.forEach(
    option => {

        option.addEventListener(
            'click',
            () => {

                const theme =
                    option.dataset.theme;


                // For now, only Light
                // and Dark are active

                if (
                    theme !== 'default' &&
                    theme !== 'dark'
                ) {

                    return;

                }


                applyStoreTheme(
                    theme
                );

            }
        );

    }
);

