function applyMainStoreProfileImage(url) {

    const targets = [

        document.querySelector(
            '.store-avatar'
        ),

        document.querySelector(
            '.profile-avatar'
        )

    ];


    targets.forEach(
        target => {

            if (!target) {
                return;
            }


            if (url) {

                target.innerHTML = '';


                const img =
                    document.createElement(
                        'img'
                    );


                img.src = url;

                img.alt =
                    'Store logo';

                img.loading =
                    'lazy';


                target.appendChild(
                    img
                );

            } else {

                target.innerHTML =
                    '<i class="fa-solid fa-store"></i>';

            }

        }
    );

}

// =========================================
// IMAGE CROPPER — SHARED CONTROLLER
// =========================================

const imageCropModal =
    document.getElementById(
        'imageCropModal'
    );


const imageCropTarget =
    document.getElementById(
        'imageCropTarget'
    );


const cancelImageCropBtn =
    document.getElementById(
        'cancelImageCropBtn'
    );


const confirmImageCropBtn =
    document.getElementById(
        'confirmImageCropBtn'
    );


let activeCropper = null;

let activeCropType = null;

let activeOriginalFile = null;

let activeObjectUrl = null;


// =========================================
// OPEN IMAGE CROPPER
// =========================================

function openImageCropper(
    file,
    type
) {

    if (!file) {
        return;
    }


    if (
        !file.type.startsWith(
            'image/'
        )
    ) {

        alert(
            'Please select an image.'
        );

        return;
    }


    // Clean up old cropper

    destroyImageCropper();


    activeOriginalFile =
        file;


    activeCropType =
        type;


    // Create temporary preview URL

    activeObjectUrl =
        URL.createObjectURL(
            file
        );


    imageCropTarget.src =
        activeObjectUrl;


    imageCropModal.classList.add(
        'active'
    );


    imageCropModal.setAttribute(
        'aria-hidden',
        'false'
    );


    // Wait until image loads

    imageCropTarget.onload =
        () => {

            let aspectRatio =
                NaN;


            // Product = square

            if (
                type === 'product'
            ) {

                aspectRatio =
                    1 / 1;

            }


            // Store cover = 16:9

            if (
                type === 'cover'
            ) {

                aspectRatio =
                    16 / 9;

            }


            activeCropper =
    new Cropper(
        imageCropTarget,
        {

            // Product = 1:1
            // Cover = 16:9
            aspectRatio:
                aspectRatio,


            // Keep the crop box inside
            // the image area
            viewMode:
                1,


            // User moves the image
            dragMode:
                'move',


            // Start with a clearly visible
            // crop rectangle
            autoCropArea:
                0.75,


            // Crop box can be moved
            cropBoxMovable:
                true,


            // Crop box can be resized
            cropBoxResizable:
                true,


            // Image can be moved
            movable:
                true,


            // Image can be zoomed
            zoomable:
                true,


            zoomOnWheel:
                true,


            responsive:
                true,


            restore:
                false,


            // Show the crop guides
            guides:
                true,


            center:
                true,


            highlight:
                true,


            toggleDragModeOnDblclick:
                false

        }
    );

        };


    console.log(
        'Image cropper opened:',
        type,
        file.name
    );

}


// =========================================
// DESTROY CROPPER
// =========================================

function destroyImageCropper() {

    if (activeCropper) {

        activeCropper.destroy();

        activeCropper =
            null;

    }


    if (activeObjectUrl) {

        URL.revokeObjectURL(
            activeObjectUrl
        );

        activeObjectUrl =
            null;

    }


    if (imageCropTarget) {

        imageCropTarget.onload =
            null;

        imageCropTarget.src =
            '';

    }

}


// =========================================
// CLOSE CROPPER
// =========================================

function closeImageCropper() {

    destroyImageCropper();


    if (imageCropModal) {

        imageCropModal.classList.remove(
            'active'
        );


        imageCropModal.setAttribute(
            'aria-hidden',
            'true'
        );

    }


    activeCropType =
        null;

    activeOriginalFile =
        null;

}


// =========================================
// CANCEL CROP
// =========================================

if (cancelImageCropBtn) {

    cancelImageCropBtn.addEventListener(
        'click',
        () => {

            closeImageCropper();

        }
    );

}


// =========================================
// CONFIRM CROP
// =========================================

if (confirmImageCropBtn) {

    confirmImageCropBtn.addEventListener(
        'click',
        () => {

            if (!activeCropper) {

                return;

            }


            let outputWidth =
                1000;

            let outputHeight =
                1000;


            // Product output

            if (
                activeCropType ===
                'product'
            ) {

                outputWidth =
                    1000;

                outputHeight =
                    1000;

            }


            // Cover output

            if (
                activeCropType ===
                'cover'
            ) {

                outputWidth =
                    1600;

                outputHeight =
                    900;

            }


            const croppedCanvas =
                activeCropper.getCroppedCanvas(
                    {

                        width:
                            outputWidth,

                        height:
                            outputHeight,

                        imageSmoothingEnabled:
                            true,

                        imageSmoothingQuality:
                            'high'

                    }
                );


            if (!croppedCanvas) {

                alert(
                    'Could not crop this image.'
                );

                return;

            }


            croppedCanvas.toBlob(
                blob => {

                    if (!blob) {

                        alert(
                            'Could not create cropped image.'
                        );

                        return;

                    }


                    const baseName =
                        activeOriginalFile?.name
                            ?.replace(
                                /\.[^/.]+$/,
                                ''
                            )
                        || 'image';


                    const croppedFile =
                        new File(
                            [

                                blob

                            ],
                            `${baseName}-cropped.jpg`,
                            {

                                type:
                                    'image/jpeg',

                                lastModified:
                                    Date.now()

                            }
                        );


                    const cropType =
                        activeCropType;


                    // Close before forwarding

                    closeImageCropper();


                    // =================================
                    // SEND CROPPED FILE TO EXISTING FLOW
                    // =================================

                    if (
                        cropType ===
                        'product'
                    ) {

                        handleProductImage(
                            croppedFile
                        );

                    }


                    if (
                        cropType ===
                        'cover'
                    ) {

                        handleStoreCoverImage(
                            croppedFile
                        );

                    }


                    console.log(
                        'Cropped image created:',
                        croppedFile
                    );

                },
                'image/jpeg',
                0.9
            );

        }
    );

}

