// Process and compress selected product image

function handleProductImage(file) {

    if (!file) {
        return;
    }

    if (!file.type.startsWith('image/')) {

        alert('Please select an image.');

        return;
    }

    const reader = new FileReader();

    reader.onload = function(event) {

        const img = new Image();

        img.onload = function() {

            // Maximum image size
            const maxWidth = 800;
            const maxHeight = 800;

            let width = img.width;
            let height = img.height;

            // Resize large images
            if (width > maxWidth || height > maxHeight) {

                const ratio = Math.min(
                    maxWidth / width,
                    maxHeight / height
                );

                width = Math.round(width * ratio);
                height = Math.round(height * ratio);
            }

            // Create canvas
            const canvas =
                document.createElement('canvas');

            canvas.width = width;
            canvas.height = height;

            const ctx =
                canvas.getContext('2d');

            ctx.drawImage(
                img,
                0,
                0,
                width,
                height
            );

            // Compress image
            selectedProductImage =
                canvas.toDataURL(
                    'image/jpeg',
                    0.7
                );

            console.log(
                'Compressed product image:',
                selectedProductImage.length,
                'characters'
            );

            // Show preview
            if (productUploadPreview) {

                productUploadPreview.innerHTML = `
                    <img
                        src="${selectedProductImage}"
                        alt="Product image preview"
                    >
                `;

            }

        };

        img.onerror = function() {

            alert(
                'Could not process this image. Please try another image.'
            );

        };

        img.src = event.target.result;
    };

    reader.onerror = function() {

        alert(
            'Could not read the image. Please try again.'
        );

    };

    reader.readAsDataURL(file);
}


// Gallery image selected

if (productImageInput) {

    productImageInput.addEventListener(
        'change',
        () => {

            const file =
                productImageInput.files?.[0];

            if (!file) {
                return;
            }

            openImageCropper(
                file,
                'product'
            );

            // Allow selecting the same image again
            productImageInput.value =
                '';

        }
    );

}

