/* =========================================
   NEXODRA AUTH - BRICK 2A
   CREATE ACCOUNT
========================================= */

document.addEventListener('DOMContentLoaded', () => {

    const signupForm = document.getElementById('signupForm');

    const signupName = document.getElementById('signupName');
    const signupCountry = document.getElementById('signupCountry');
    const signupEmail = document.getElementById('signupEmail');
    const signupPassword = document.getElementById('signupPassword');

    const signupBtn = document.getElementById('signupBtn');
    const signupMessage = document.getElementById('signupMessage');


    // Stop safely if the signup screen is not present
    if (
        !signupForm ||
        !signupName ||
        !signupEmail ||
        !signupPassword ||
        !signupBtn ||
        !signupMessage
    ) {
        return;
    }


    signupForm.addEventListener('submit', async (event) => {

        event.preventDefault();


        const name =
            signupName.value.trim();

      const countryCode = signupCountry
    ? signupCountry.value.trim()
    : '';

const countryName = signupCountry &&
    signupCountry.selectedIndex >= 0
        ? signupCountry.options[
            signupCountry.selectedIndex
          ].textContent.trim()
        : '';

        const email =
            signupEmail.value.trim();

        const password =
            signupPassword.value;


        // Clear previous message
        signupMessage.textContent = '';

        signupMessage.style.color = '#dc2626';


        // Basic validation
        if (!name) {

            signupMessage.textContent =
                'Please enter your name.';

            signupName.focus();

            return;
        }


        if (!email) {

            signupMessage.textContent =
                'Please enter your email address.';

            signupEmail.focus();

            return;
        }


        if (password.length < 6) {

            signupMessage.textContent =
                'Password must be at least 6 characters.';

            signupPassword.focus();

            return;
        }

      if (!countryCode || !countryName) {
    signupMessage.textContent =
        'Please select your country of operation.';

    document.getElementById('signupCountryTrigger')?.focus();

    return;
}

        // Loading state
        signupBtn.disabled = true;

        signupBtn.innerHTML = `
            <span>Creating account...</span>
            <i class="fa-solid fa-spinner fa-spin"></i>
        `;


        try {
  
            /*
             * Create the Supabase Auth account.
             *
             * The name is stored as user metadata.
             */
            const {
    data,
    error
} = await supabaseClient.auth.signUp({

    email: email,

    password: password,

    options: {

        emailRedirectTo: 'https://kafudemshafiki-cell.github.io/nexodra-seller-app/',

       data: {
    name: name,
    country: countryName,
    country_code: countryCode
} 

    }

});
   
            // Supabase returned an error
            if (error) {

                console.error(
                    'Signup error:',
                    error
                );

                signupMessage.textContent =
                    error.message ||
                    'Unable to create your account.';

                return;
            }


            /*
             * Account created successfully.
             *
             * If email confirmation is enabled,
             * Supabase normally returns a user but
             * no active session yet.
             */
            if (data.user && !data.session) {

                signupMessage.style.color =
                    '#16a34a';

                signupMessage.textContent =
                    'Account created! Check your email to confirm your account.';

                signupForm.reset();

                return;
            }


            /*
             * If email confirmation is disabled,
             * a session may be available immediately.
             */
            if (data.user && data.session) {

                signupMessage.style.color =
                    '#16a34a';

                signupMessage.textContent =
                    'Account created successfully!';

                /*
                 * We are NOT switching screens yet.
                 *
                 * That will be handled in Brick 3
                 * when we build the login/session system.
                 */

                signupForm.reset();

                return;
            }


            signupMessage.textContent =
                'Account creation completed. Please try signing in.';

        } catch (error) {

            console.error(
                'Unexpected signup error:',
                error
            );

            signupMessage.textContent =
                'Something went wrong. Please try again.';

        } finally {

            // Restore button
            signupBtn.disabled = false;

            signupBtn.innerHTML = `
                <span>Create Account</span>
                <i class="fa-solid fa-arrow-right"></i>
            `;

        }

    });

});
/* =========================================
   NEXODRA AUTH - PANEL SWITCHING
========================================= */

document.addEventListener('DOMContentLoaded', () => {

    const loginPanel =
        document.getElementById('loginPanel');

    const signupPanel =
        document.getElementById('signupPanel');

    const showSignupBtn =
        document.getElementById('showSignupBtn');

    const showLoginBtn =
        document.getElementById('showLoginBtn');


    if (
        !loginPanel ||
        !signupPanel ||
        !showSignupBtn ||
        !showLoginBtn
    ) {
        return;
    }


    // Open Create Account
    showSignupBtn.addEventListener('click', () => {

        loginPanel.classList.remove('active');

        signupPanel.classList.add('active');

        // Clear old messages
        const loginMessage =
            document.getElementById('loginMessage');

        if (loginMessage) {
            loginMessage.textContent = '';
        }

    });


    // Return to Sign In
    showLoginBtn.addEventListener('click', () => {

        signupPanel.classList.remove('active');

        loginPanel.classList.add('active');

        // Clear old messages
        const signupMessage =
            document.getElementById('signupMessage');

        if (signupMessage) {
            signupMessage.textContent = '';
        }

    });

});
/* =========================================
   AUTH PASSWORD VISIBILITY
========================================= */

document.addEventListener('DOMContentLoaded', () => {

    function setupPasswordToggle(
        toggleId,
        inputId
    ) {

        const toggle =
            document.getElementById(toggleId);

        const input =
            document.getElementById(inputId);

        if (!toggle || !input) {
            return;
        }


        toggle.addEventListener('click', () => {

            const isPassword =
                input.type === 'password';

            input.type =
                isPassword ? 'text' : 'password';


            const icon =
                toggle.querySelector('i');

            if (icon) {

                icon.className =
                    isPassword
                        ? 'fa-regular fa-eye-slash'
                        : 'fa-regular fa-eye';

            }

        });

    }


    setupPasswordToggle(
        'loginPasswordToggle',
        'loginPassword'
    );


    setupPasswordToggle(
        'signupPasswordToggle',
        'signupPassword'
    );

});

/* =========================================
   NEXODRA FOUNDER AUTHORIZATION CHECK
   On-page status diagnostic (no console required)
========================================= */

function nexodraShowFounderCheckStatus(status) {
    window.nexodraFounderCheckStatus = status;

    const messages = {
        checking: 'Checking Founder access…',
        authorized: 'Founder access verified.',
        denied: 'Founder access is not enabled for this account.',
        signed_out: 'Founder check: session not available. Please sign in again.',
        unavailable: 'Founder check could not reach the backend. Seller access is unchanged.'
    };

    let notice = document.getElementById('nexodraFounderCheckNotice');
    if (!notice && document.body) {
        notice = document.createElement('div');
        notice.id = 'nexodraFounderCheckNotice';
        notice.setAttribute('role', 'status');
        notice.setAttribute('aria-live', 'polite');
        Object.assign(notice.style, {
            position: 'fixed',
            left: '50%',
            bottom: '22px',
            transform: 'translateX(-50%)',
            zIndex: '2147483000',
            maxWidth: 'calc(100vw - 32px)',
            padding: '12px 18px',
            borderRadius: '10px',
            background: '#17212b',
            color: '#ffffff',
            boxShadow: '0 4px 18px rgba(0,0,0,.25)',
            fontSize: '14px',
            lineHeight: '1.4',
            textAlign: 'center'
        });
        document.body.appendChild(notice);
    }

    if (notice) {
        notice.textContent = messages[status] || 'Founder access check updated.';
        notice.style.display = 'block';
        if (window.nexodraFounderNoticeTimer) {
            clearTimeout(window.nexodraFounderNoticeTimer);
        }
        if (status !== 'checking') {
            window.nexodraFounderNoticeTimer = setTimeout(() => {
                const current = document.getElementById('nexodraFounderCheckNotice');
                if (current) current.style.display = 'none';
            }, 9000);
        }
    }
}

async function nexodraCheckFounderAccess(existingSession = null) {
    window.nexodraFounderAuthorized = false;
    window.nexodraFounderUserId = null;
    nexodraShowFounderCheckStatus('checking');

    try {
        let session = existingSession;

        // Only retrieve the session if the caller
        // did not already provide one.
        if (!session) {
            const {
                data,
                error: sessionError
            } = await supabaseClient.auth.getSession();

            if (sessionError || !data.session) {
                nexodraShowFounderCheckStatus('signed_out');
                return false;
            }

            session = data.session;
        }

        if (!session.user || !session.access_token) {
            nexodraShowFounderCheckStatus('signed_out');
            return false;
        }

        const response = await fetch(
            `${NEXODRA_API_URL}/founder-check`,
            {
                method: 'GET',
                headers: {
                    Authorization: `Bearer ${session.access_token}`
                }
            }
        );

        if (response.status === 403) {
            nexodraShowFounderCheckStatus('denied');
            return false;
        }

        if (response.status === 401) {
            nexodraShowFounderCheckStatus('signed_out');
            return false;
        }

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }

        const result = await response.json();

        const isFounder =
            result.status === 'authorized' &&
            result.role === 'founder' &&
            result.user_id === session.user.id;

        if (!isFounder) {
            nexodraShowFounderCheckStatus('denied');
            return false;
        }

        window.nexodraFounderAuthorized = true;
        window.nexodraFounderUserId = session.user.id;
        nexodraShowFounderCheckStatus('authorized');

        return true;

    } catch (error) {
        nexodraShowFounderCheckStatus('unavailable');

        console.error(
            'Nexodra Founder check unavailable:',
            error.message
        );

        return false;
    }
}

