async function nexodraApiHealthCheck() {

    try {

        const response =
            await fetch(
                `${NEXODRA_API_URL}/health`
            );

        if (!response.ok) {
            throw new Error(
                `HTTP ${response.status}`
            );
        }

        const data =
            await response.json();

        console.log(
            'C10-D — Nexodra Python API connected:',
            data
        );

        return data;

    } catch (error) {

        console.error(
            'C10-D — Nexodra Python API connection failed:',
            error
        );

        return null;
    }
}

