/* =========================================================
   6. CHART SYSTEM
   Uses Chart.js when available.
   Includes a native Canvas fallback.
   ========================================================= */

const chartInstances = new Map();

const chartPalette = {
  purple: "#8b5cf6",
  blue: "#3b82f6",
  cyan: "#06b6d4",
  green: "#10b981",
  orange: "#f59e0b",
  pink: "#ec4899",
  red: "#ef4444",
  grid: "rgba(148, 163, 184, 0.14)",
  text: "#94a3b8"
};

function getChartTheme() {
  const dark =
    document.documentElement.dataset.theme === "dark" ||
    document.body.classList.contains("dark-mode");

  return {
    text: dark ? "#cbd5e1" : "#64748b",
    grid: dark
      ? "rgba(148,163,184,0.13)"
      : "rgba(100,116,139,0.12)"
  };
}

function makeGradient(context, color) {
  const gradient = context.createLinearGradient(
    0,
    0,
    0,
    320
  );

  gradient.addColorStop(0, `${color}55`);
  gradient.addColorStop(1, `${color}00`);

  return gradient;
}


function initializeCharts() {

  // NEXUS owns every chart inside its dashboard.
  // Nexodra's original chart engine must not create
  // competing Chart.js instances on those canvases.

  document.querySelectorAll("canvas[data-chart]").forEach((canvas) => {

    if (canvas.closest("#nexusDashboard")) return;

    const type = canvas.dataset.chart;

    const labels = (
      canvas.dataset.labels ||
      "Mon,Tue,Wed,Thu,Fri,Sat,Sun"
    ).split(",");

    const values = (
      canvas.dataset.values ||
      "18,28,23,39,32,48,42"
    ).split(",").map(Number);

    const color = canvas.dataset.color || chartPalette.purple;

    createChart(canvas, {
      type,
      labels,
      values,
      color
    });

  });

  // Original Nexodra charts remain available
  // outside the NEXUS dashboard.

  const defaultCharts = [
    {
      selectors: ["#revenueChart", "#mainChart"],
      type: "line",
      labels: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
      values: [24, 38, 31, 52, 43, 67, 58],
      color: chartPalette.purple
    },
    {
      selectors: ["#activityChart"],
      type: "bar",
      labels: ["Jan", "Feb", "Mar", "Apr", "May", "Jun"],
      values: [35, 52, 43, 68, 57, 82],
      color: chartPalette.blue
    },
    {
      selectors: ["#trafficChart"],
      type: "doughnut",
      labels: ["Direct", "Social", "Search", "Referral"],
      values: [35, 25, 28, 12],
      color: chartPalette.purple
    }
  ];

  defaultCharts.forEach((config) => {

    for (const selector of config.selectors) {

      const canvas = document.querySelector(selector);

      if (
        !canvas ||
        canvas.closest("#nexusDashboard") ||
        chartInstances.has(canvas)
      ) continue;

      createChart(canvas, config);
      break;

    }

  });

}



/* =========================================================
   BRICK 1 — PREPARE REAL REVENUE CHART DATA
   Uses sales already loaded from Supabase.
   ========================================================= */

function prepareRevenueChartData(sales, range = '30d') {

  const now = new Date();

  let days = 30;

  if (range === '7d') {
    days = 7;
  } else if (range === '90d') {
    days = 90;
  } else if (range === '1y') {
    days = 365;
  }

  const labels = [];
  const values = [];

  const startDate = new Date(now);

  startDate.setHours(0, 0, 0, 0);
  startDate.setDate(startDate.getDate() - (days - 1));

  for (let i = 0; i < days; i++) {

    const date = new Date(startDate);

    date.setDate(startDate.getDate() + i);

    labels.push(
      date.toLocaleDateString('en-US', {
        month: 'short',
        day: '2-digit'
      })
    );

    values.push(0);

  }

  (sales || []).forEach((sale) => {

    if (!sale.created_at) return;

    const saleDate = new Date(sale.created_at);

    if (Number.isNaN(saleDate.getTime())) return;

    saleDate.setHours(0, 0, 0, 0);

    const dayDifference = Math.floor(
      (saleDate.getTime() - startDate.getTime()) /
      (1000 * 60 * 60 * 24)
    );

    if (
      dayDifference >= 0 &&
      dayDifference < days
    ) {

      values[dayDifference] += Number(
        sale.total || 0
      );

    }

  });

  return {
    labels,
    values
  };

}

function createChart(canvas, config) {
  if (!canvas || chartInstances.has(canvas)) return;

  if (typeof Chart !== "undefined") {
    createChartJS(canvas, config);
  } else {
    drawNativeChart(canvas, config);
  }
}

/* =========================================================
   BRICK 3 — UPDATE REVENUE CHART
   Uses the existing Chart.js / Canvas chart system.
   ========================================================= */

function updateRevenueChart(canvas, chartData) {

  if (!canvas || !chartData) {
    console.warn(
      'BRICK 3 — Missing Revenue canvas or chart data.'
    );

    return;
  }

  const config = {
    type: 'line',
    labels: chartData.labels,
    values: chartData.values,
    color: chartPalette.purple,
    label: 'Revenue'
  };

  const existingChart = chartInstances.get(canvas);

  if (
    existingChart &&
    typeof existingChart.update === 'function'
  ) {

    existingChart.data.labels = config.labels;

    existingChart.data.datasets[0].data =
      config.values;

    existingChart.update();

    console.log(
      'BRICK 3 — Existing Revenue chart updated.'
    );

    return;
  }

  if (existingChart) {
    chartInstances.delete(canvas);
  }

  createChart(canvas, config);

  console.log(
    'BRICK 3 — Revenue chart created.'
  );

}

function createChartJS(canvas, config) {

  const prefersReducedMotion =
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  
  const context = canvas.getContext("2d");

  const theme = getChartTheme();

  const isDoughnut = config.type === "doughnut";
  const isBar = config.type === "bar";

  const dataset = {
    label: config.label || "Performance",
    data: config.values,
    borderColor: config.color,
    backgroundColor: isDoughnut
      ? [
          chartPalette.purple,
          chartPalette.blue,
          chartPalette.cyan,
          chartPalette.green
        ]
      : isBar
        ? `${config.color}cc`
        : makeGradient(context, config.color),
    borderWidth: isDoughnut ? 0 : 2.5,
    borderRadius: isBar ? 8 : 0,
    fill: !isBar && !isDoughnut,
    tension: 0.4,
    pointRadius: isDoughnut ? 0 : 3,
    pointHoverRadius: 6,
    pointBackgroundColor: config.color,
    pointBorderColor: "#ffffff",
    pointBorderWidth: 2
  };
const chart = new Chart(context, {
    type: config.type,
    data: {
      labels: config.labels,
      datasets: [dataset]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: {
        duration: prefersReducedMotion ? 0 : 1200,
        easing: "easeOutQuart"
      },
      interaction: {
        intersect: false,
        mode: "index"
      },
      plugins: {
        legend: {
          display: isDoughnut,
          position: "bottom",
          labels: {
            color: theme.text,
            usePointStyle: true,
            pointStyle: "circle",
            padding: 18
          }
        },
        tooltip: {
          backgroundColor: "#111827",
          titleColor: "#ffffff",
          bodyColor: "#e5e7eb",
          padding: 12,
          cornerRadius: 10,
          displayColors: true
        }
      },
      scales: isDoughnut
        ? {}
        : {
            x: {
              grid: {
                display: false
              },
              border: {
                display: false
              },
              ticks: {
                color: theme.text
              }
            },
            y: {
              beginAtZero: true,
              border: {
                display: false,
                dash: [4, 4]
              },
              grid: {
                color: theme.grid
              },
              ticks: {
                color: theme.text,
                padding: 10
              }
            }
          }
    }
  });

  chartInstances.set(canvas, chart);
}
/*
  Native Canvas chart fallback.
  This keeps basic charts working without Chart.js.
*/

function drawNativeChart(canvas, config) {
  const context = canvas.getContext("2d");

  if (!context) return;

  const ratio = window.devicePixelRatio || 1;

  const bounds = canvas.getBoundingClientRect();

  const width = Math.max(bounds.width, 280);
  const height = Math.max(bounds.height, 180);

  canvas.width = width * ratio;
  canvas.height = height * ratio;

  context.scale(ratio, ratio);

  const padding = {
    top: 24,
    right: 18,
    bottom: 34,
    left: 38
  };

  const chartWidth =
    width - padding.left - padding.right;

  const chartHeight =
    height - padding.top - padding.bottom;

  const values = config.values;
  const maxValue = Math.max(...values, 1) * 1.15;

  const theme = getChartTheme();

  context.clearRect(0, 0, width, height);

  // Horizontal grid lines.
  context.strokeStyle = theme.grid;
  context.lineWidth = 1;

  for (let i = 0; i <= 4; i++) {
    const y =
      padding.top + (chartHeight / 4) * i;

    context.beginPath();
    context.moveTo(padding.left, y);
    context.lineTo(width - padding.right, y);
    context.stroke();
  }

  if (config.type === "doughnut") {
    const total = values.reduce(
      (sum, value) => sum + value,
      0
    );
   const colors = [
      chartPalette.purple,
      chartPalette.blue,
      chartPalette.cyan,
      chartPalette.green
    ];

    let angle = -Math.PI / 2;

    const centerX = width / 2;
    const centerY = height / 2 - 8;
    const radius = Math.min(width, height) * 0.32;

    values.forEach((value, index) => {
      const slice = (value / total) * Math.PI * 2;

      context.beginPath();
      context.arc(
        centerX,
        centerY,
        radius,
        angle,
        angle + slice
      );

      context.strokeStyle = colors[index % colors.length];
      context.lineWidth = radius * 0.38;
      context.stroke();

      angle += slice;
    });

    chartInstances.set(canvas, {
      config,
      redraw: () => drawNativeChart(canvas, config)
    });

    return;
  }
 const points = values.map((value, index) => {
    const x =
      padding.left +
      (values.length === 1
        ? chartWidth / 2
        : (chartWidth / (values.length - 1)) * index);

    const y =
      padding.top +
      chartHeight -
      (value / maxValue) * chartHeight;

    return { x, y };
  });

  if (config.type === "bar") {
    const slotWidth = chartWidth / values.length;
    const barWidth = slotWidth * 0.55;

    points.forEach((point, index) => {
      const barHeight =
        padding.top + chartHeight - point.y;

      context.fillStyle = config.color;

      context.beginPath();

      context.roundRect(
        point.x - barWidth / 2,
        point.y,
        barWidth,
        barHeight,
        5
      );

      context.fill();
    });
  } else {
  // Fill the area beneath the line.
    context.beginPath();
    context.moveTo(points[0].x, padding.top + chartHeight);

    points.forEach((point) => {
      context.lineTo(point.x, point.y);
    });

    context.lineTo(
      points[points.length - 1].x,
      padding.top + chartHeight
    );

    context.closePath();

    const gradient = context.createLinearGradient(
      0,
      padding.top,
      0,
      padding.top + chartHeight
    );

    gradient.addColorStop(0, `${config.color}45`);
    gradient.addColorStop(1, `${config.color}00`);

    context.fillStyle = gradient;
    context.fill();

    // Smooth line.
    context.beginPath();

    points.forEach((point, index) => {
      if (index === 0) {
        context.moveTo(point.x, point.y);
      } else {
        const previous = points[index - 1];

        const midX = (previous.x + point.x) / 2;
        const midY = (previous.y + point.y) / 2;

        context.quadraticCurveTo(
          previous.x,
          previous.y,
          midX,
          midY
        );
      }
    });

    const last = points[points.length - 1];

    context.lineTo(last.x, last.y);

    context.strokeStyle = config.color;
    context.lineWidth = 3;
    context.lineJoin = "round";
    context.stroke();

    // Data points.
    points.forEach((point) => {
      context.beginPath();
      context.arc(point.x, point.y, 3.5, 0, Math.PI * 2);

      context.fillStyle = config.color;
      context.fill();
    });
  }

  // X-axis labels.
  context.fillStyle = theme.text;
  context.font = "11px system-ui, sans-serif";
  context.textAlign = "center";

  config.labels.forEach((label, index) => {
    const x =
      padding.left +
      (values.length === 1
        ? chartWidth / 2
        : (chartWidth / (values.length - 1)) * index);

    context.fillText(
      label.trim(),
      x,
      height - 10
    );
  });

  chartInstances.set(canvas, {
    config,
    redraw: () => drawNativeChart(canvas, config)
  });
}

