/* =========================================
   BRICK 3A — SUBSCRIBE AND SAVE TO BACKEND
========================================= */

function nexodraDecodeVapidPublicKey(base64String) {
    const padding = "=".repeat((4 - base64String.length % 4) % 4);

    const base64 = (base64String + padding)
        .replace(/-/g, "+")
        .replace(/_/g, "/");

    const raw = atob(base64);

    return Uint8Array.from(raw, char => char.charCodeAt(0));
}


async function nexodraSubscribeToPush() {

    const output = document.getElementById(
        'nexodra-push-permission-result'
    );

    function report(message) {
        if (output) output.textContent = message;
        console.log('PUSH REGISTRATION:', message);
    }

    try {

        report('CHECK 1: Checking browser push support...');

        if (
            !('serviceWorker' in navigator) ||
            !('PushManager' in window) ||
            !('Notification' in window)
        ) {
            throw new Error('Required browser notification features are unavailable.');
        }

        if (
            typeof NEXODRA_API_URL === 'undefined' ||
            typeof NEXODRA_VAPID_PUBLIC_KEY === 'undefined' ||
            typeof supabaseClient === 'undefined'
        ) {
            throw new Error('Nexodra configuration is missing.');
        }

        report('CHECK 2: Checking notification permission...');

        if (Notification.permission !== 'granted') {
            const permission = await Notification.requestPermission();

            if (permission !== 'granted') {
                throw new Error('Notification permission was not granted.');
            }
        }

        report('CHECK 3: Retrieving signed-in seller session...');

        const { data, error } =
            await supabaseClient.auth.getSession();

        if (error) throw error;

        const session = data.session;

        if (!session?.access_token) {
            throw new Error('Please sign in again.');
        }

        report('CHECK 4: Waiting for active service worker...');

        const registration = await Promise.race([
            navigator.serviceWorker.ready,
            new Promise((_, reject) =>
                setTimeout(
                    () => reject(new Error(
                        'Timed out waiting for the service worker to become active.'
                    )),
                    15000
                )
            )
        ]);

        if (!registration.active) {
            throw new Error('Service worker has no active worker.');
        }

        report('CHECK 5: Checking existing browser subscription...');

        let subscription =
            await registration.pushManager.getSubscription();

        if (!subscription) {

            report('CHECK 6: Creating a new browser subscription...');

            subscription = await registration.pushManager.subscribe({
                userVisibleOnly: true,
                applicationServerKey:
                    nexodraDecodeVapidPublicKey(
                        NEXODRA_VAPID_PUBLIC_KEY
                    )
            });
        }

        const json = subscription.toJSON();

        if (!json.endpoint || !json.keys?.p256dh || !json.keys?.auth) {
            throw new Error('Browser returned an incomplete subscription.');
        }

        report('CHECK 7: Sending subscription to Nexodra backend...');

        const response = await fetch(
            `${NEXODRA_API_URL}/push/subscribe`,
            {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${session.access_token}`
                },
                body: JSON.stringify({
                    endpoint: json.endpoint,
                    p256dh: json.keys.p256dh,
                    auth: json.keys.auth
                })
            }
        );

        const result = await response.json().catch(() => ({}));

        if (!response.ok) {
            throw new Error(
                result.detail || `Backend returned HTTP ${response.status}.`
            );
        }

        report('SUCCESS: Backend saved the browser subscription.');

        return {
            success: true,
            message: 'Push subscription saved.'
        };

    } catch (error) {

        report('REGISTRATION FAILED: ' + error.message);

        console.error('PUSH REGISTRATION ERROR:', error);

        return {
            success: false,
            message: error.message || 'Push registration failed.'
        };
    }
}


// =========================================
// NEXODRA PUSH — RECEIVE SERVICE WORKER DIAGNOSTICS
// =========================================

if (
    'serviceWorker' in navigator &&
    !window.nexodraPushDiagnosticListenerAdded
) {
    window.nexodraPushDiagnosticListenerAdded = true;

    navigator.serviceWorker.addEventListener(
        'message',
        event => {

            const data = event.data;

            if (
                !data ||
                data.type !== 'NEXODRA_PUSH_DIAGNOSTIC'
            ) {
                return;
            }

            const diagnosticsPanel =
                document.getElementById(
                    'nexodra-push-diagnostics'
                );

            if (!diagnosticsPanel) {
                return;
            }

            const timestamp =
                data.timestamp || new Date().toLocaleTimeString();

            diagnosticsPanel.textContent +=
                '\n[' + timestamp + '] ' +
                (data.level || 'info').toUpperCase() +
                ': ' +
                (data.message || 'No diagnostic message.');

            console.log(
                'NEXODRA PUSH DIAGNOSTIC:',
                data
            );
        }
    );
}


/* =========================================
   BRICK 3B — SEND BACKEND TEST PUSH
========================================= */

async function nexodraSendBackendPushTest() {
    try {
        const { data, error } =
            await supabaseClient.auth.getSession();

        if (error) throw error;

        const session = data.session;

        if (!session?.access_token) {
            throw new Error("Please sign in before testing push notifications.");
        }

        const response = await fetch(
            `${NEXODRA_API_URL}/push/test`,
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": `Bearer ${session.access_token}`
                },
                body: JSON.stringify({
                    title: "Nexodra push test",
                    body: "Your backend push notification reached the send request.",
                })
            }
        );

        const result = await response.json().catch(() => ({}));

        if (!response.ok) {
            throw new Error(
                result.detail || `Push test failed (${response.status}).`
            );
        }

        console.info("BRICK 3B — Backend push test response:", result);

        return {
            success: true,
            message: "Backend accepted the push send request.",
            result
        };

    } catch (error) {
        console.error("BRICK 3B — Backend push test failed:", error);

        return {
            success: false,
            message: error.message || "Backend push test failed."
        };
    }
}


/* =========================================
   BRICK 3C — ENABLE PUSH BUTTON
========================================= */

(function nexodraSetupEnablePushButton() {

    const button = document.getElementById(
        "nexodra-enable-push"
    );

    const resultElement = document.getElementById(
        "nexodra-enable-push-result"
    );

    if (!button || !resultElement) {
        console.warn(
            "BRICK 3C — Push button or result element not found."
        );
        return;
    }

    button.addEventListener("click", async function () {

        button.disabled = true;
        button.textContent = "Enabling Push...";
        resultElement.textContent =
            "Creating or checking your push subscription...";

        try {

            if (
                typeof nexodraSubscribeToPush !== "function"
            ) {
                throw new Error(
                    "nexodraSubscribeToPush() is not available."
                );
            }

            const result = await nexodraSubscribeToPush();

            if (!result || result.success !== true) {
                throw new Error(
                    result?.message ||
                    "Push subscription could not be saved."
                );
            }

            resultElement.textContent =
                "SUCCESS — " + result.message;

            button.textContent = "Push Enabled";

            console.info(
                "BRICK 3C — Push enabled successfully."
            );

        } catch (error) {

            resultElement.textContent =
                "FAILED — " +
                (error.message || "Unknown error");

            button.textContent = "Try Again";

            console.error(
                "BRICK 3C — Enable push failed:",
                error
            );

        } finally {

            button.disabled = false;

        }

    });

})();


