    agreements.forEach(agreement => {

        const view =
            getAgreementView(agreement);

        const balance =
            Math.max(
                0,
                Number(view.balance || 0)
            );

        totalOutstanding += balance;

        if (view.status === 'overdue') {
            overdueAgreements++;
        }

        if (view.status === 'fulfilled') {
            fulfilledAgreements++;
        }

    });

    // -------------------------------------
